import {EVENTS,RULE_ISSUES,categories,makeDraw,resolveDraw,saveWinner,clearWinner,signature,clubConflicts,fingerprintCounts,initialState,validateAthlete,classify} from './engine.js';
import {icon} from './icons.js';
import * as Client from './client.js';
import {ROLES,STATUSES,ageAt,managesTournament,managesProfile,canEnter} from './workspace.js';
import {t as T,LANGUAGES,STORAGE_KEY as LANGUAGE_KEY,getLanguage,setLanguage,onLanguageChange,locale,formatNumber,gradeName,gradeLabel,ruleLabel,ruleText,translateMessage} from './i18n.js';
import {warsawToday} from './guest-view.js';
import {AD,ACCESS} from './promo.js';
const isDemo=Client.isDemo;
const eventName=key=>ruleLabel(EVENTS[key]),roleName=role=>T(ROLES[role]),statusName=status=>T(STATUSES[status]);
const plural=(n,one,few,many)=>n===1?one:n%10>=2&&n%10<=4&&(n%100<12||n%100>14)?few:many;
let workspace=null,state={tournament:{},athletes:[],draws:{},activity:[]},saving=false;
let activeId=sessionStorage.getItem('matdraw.activeTournament');
const ui={page:'tournaments',category:null,search:'',event:'all',filter:'all',rosterSearch:'',rosterFilter:'all',round:0,menu:false,screenPart:0,screenAuto:false,databaseSearch:'',tournamentSearch:'',showArchive:false};
let previousFocus=null,loginMessage='',ready=false;
// Public side (no session): upcoming list on the login screen, the sponsor dialog and the read-only guest preview.
let afterModalClose=null,promo=null,guest=null;
const upcoming={data:null,error:false,loading:false,at:0};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const athlete=id=>state.athletes.find(a=>a.id===id);
const short=n=>n.split(' ').map((p,i)=>i===0?p:p).join(' ');
const initials=n=>esc(n.trim().split(/\s+/).slice(0,2).map(p=>p[0]).join(''));
const button=(label,action,cls='secondary',extra='')=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`;
const badge=(text,type='neutral')=>`<span class="badge ${type}">${text}</span>`;
const logo=`<span class="brand-mark">${icon('bracket')}</span><span class="wordmark">MatBravo<span class="brand-dot">.</span></span>`;
const footer=()=>`<footer class="footer"><span>MatBravo <span class="footer-dot">·</span> ${T('Turniej pod kontrolą.')}</span><a class="creator" href="https://mdcse.com" target="_blank" rel="noopener noreferrer" aria-label="${T('Wykonano przez MEDUCASE — przejdź do mdcse.com')}"><span>${T('Wykonano przez')}</span><img src="./assets/meducase.png" alt="MEDUCASE" width="150" height="48"></a></footer>`;
const langSwitch=()=>`<div class="lang-switch" role="group" aria-label="Język / Language">${[['pl','PL','Polski'],['en','EN','English']].map(([code,label,name])=>`<button type="button" class="lang-option" data-set-lang="${code}" lang="${code}" aria-pressed="${getLanguage()===code}" aria-label="${name}" title="${name}">${label}</button>`).join('')}</div>`;
function allCats(){return categories(state.athletes);}
function selected(){const items=allCats().items;return items.find(c=>c.id===ui.category)||items[0];}
function ensureDraw(c){return c?state.draws[c.id]||null:null;}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),4800);}
function stats(){const s=fingerprintCounts(state.athletes);return `<div class="stats"><div class="stat"><span class="stat-icon">${icon('users')}</span><div><strong>${s.active}</strong><span>${T('Zawodników')}</span></div><small>${T('{n} klubów',{n:s.clubs})}</small></div><div class="stat"><span class="stat-icon">${icon('bracket')}</span><div><strong>${s.categories}</strong><span>${T('Kategorii')}</span></div><small>${T('{n} z min. 3 osobami',{n:s.categories-s.alerts})}</small></div><div class="stat"><span class="stat-icon">${icon('clipboard')}</span><div><strong>${state.athletes.filter(a=>a.presence==='present').length}<em>/${s.athletes}</em></strong><span>${T('Po kontroli')}</span></div><small>${T('Waga i obecność')}</small></div><button class="stat stat-alert" data-action="attention"><span class="stat-icon">${icon('alert')}</span><div><strong>${s.alerts+s.unassigned}</strong><span>${T('Wymagają uwagi')}</span></div><small>${T('Sprawdź')} ${icon('arrow')}</small></button></div>`;}
function shell(content,title,subtitle,actions=''){
 const user=workspace.user,t=state.tournament,s=fingerprintCounts(state.athletes),club=workspace.clubs.find(c=>c.id===user.clubId);
 const globalNav=[['tournaments','trophy',T('Turnieje')],['database','users',T('Baza zawodników')],...(user.role==='admin'?[['accounts','shield',T('Konta i role')]]:[])];
 const eventNav=t.id?[...(user.role!=='club'?[['overview','grid',T('Przegląd turnieju')]]:[]),['athletes','users',user.role==='club'?T('Zgłoszenia klubu'):T('Zgłoszenia')],...(user.role!=='club'?[['checkin','clipboard',T('Kontrola startowa')],['draws','bracket',T('Drabinki')]]:[])]:[];
 const nav=items=>items.map(([page,i,name])=>`<button class="nav-link ${ui.page===page?'active':''}" data-page="${page}" ${ui.page===page?'aria-current="page"':''}>${icon(i)}<span>${name}</span>${page==='athletes'?'<span class="nav-count">'+s.athletes+'</span>':''}</button>`).join('');
 return `<div class="app-shell"><aside class="sidebar ${ui.menu?'open':''}" aria-label="${T('Nawigacja główna')}"><a href="#tournaments" class="brand" data-page="tournaments" aria-label="${T('MatBravo — turnieje')}">${logo}</a><nav>${nav(globalNav)}</nav><div class="nav-divider"></div><label class="sidebar-label" for="active-tournament">${T('AKTYWNY TURNIEJ')}</label><select id="active-tournament" class="tournament-switch" data-control="tournament">${workspace.tournaments.map(x=>`<option value="${x.id}" ${t.id===x.id?'selected':''}>${esc(x.name)}</option>`).join('')||'<option>'+T('Brak turniejów')+'</option>'}</select><nav>${nav(eventNav)}${t.id&&user.role!=='club'?`<button class="nav-link" data-action="project">${icon('screen')}<span>${T('Ekran hali')}</span>${icon('external','nav-end')}</button>`:''}</nav><div class="sidebar-bottom"><div class="demo-note"><span class="pulse-dot"></span><strong>${isDemo?T('Podgląd demonstracyjny'):T('Połączono z serwerem')}</strong><p>${isDemo?T('Dane i konta testowe w tej przeglądarce.'):T('Wspólna baza zawodników i turniejów.')}</p></div><button class="nav-link" data-page="rules">${icon('settings')}<span>${T('Zasady turnieju')}</span></button><button class="nav-link" data-page="architecture">${icon('info')}<span>${T('O projekcie')}</span></button><div class="profile"><span class="avatar organizer">${initials(club?.name||T('Klub'))}</span><div><strong>${esc(roleName(user.role))}</strong><span>${esc(club?.name||'')}</span></div></div><button class="nav-link compact-nav" data-action="my-account">${icon('settings')}<span>${T('Moje konto')}</span></button><button class="nav-link compact-nav" data-action="logout">${icon('left')}<span>${T('Wyloguj się')}</span></button></div></aside>${ui.menu?'<button class="nav-backdrop" data-action="menu" aria-label="'+T('Zamknij menu')+'"></button>':''}<div class="main-shell"><header class="topbar"><div class="topbar-left"><button class="icon-btn mobile-only" data-action="menu" aria-label="${T('Otwórz menu')}">${icon('menu')}</button><span class="breadcrumb">${['tournaments','database','accounts'].includes(ui.page)?'MatBravo':esc(t.name||'MatBravo')}</span>${icon('right','crumb-arrow')}<span class="breadcrumb current">${title}</span></div><div class="topbar-right">${isDemo?'<span class="demo-badge">DEMO</span>':''}<button class="text-btn" data-action="refresh" aria-label="${T('Odśwież dane')}">${icon('refresh')}<span>${saving?T('Zapisywanie…'):isDemo?T('Zapis lokalny'):T('Dane z serwera')}</span></button>${langSwitch()}<span class="avatar organizer small" title="${esc(roleName(user.role))}">${initials(club?.name||T('Klub'))}</span></div></header><main id="main" class="main"><div class="page-heading"><div><div class="eyebrow">${['tournaments','database','accounts'].includes(ui.page)?T('PRZESTRZEŃ MATBRAVO'):T('CENTRUM TURNIEJU')}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="heading-actions">${actions}</div></div>${content}</main>${footer()}</div></div>`;
}
function roundName(index,total){const remaining=total-index;return remaining===1?T('Finał'):remaining===2?T('Półfinały'):remaining===3?T('Ćwierćfinały'):remaining===4?T('1/8 finału'):remaining===5?T('1/16 finału'):T('1/32 finału');}
function matchHtml(m,{interactive=true,compact=false}={}){
 const a=athlete(m.a),b=athlete(m.b);
 if(m.auto&&!a&&!b)return '<div class="empty-match" aria-label="'+T('Pusta gałąź')+'"></div>';
 const title=m.recorded?T('Zakończona'):m.auto?T('Wolny los'):m.ready?T('Do rozegrania'):T('Oczekiwanie');
 const row=(p,id,settled,side)=>`<div class="fighter ${side} ${m.winner===id&&id?'winner':''} ${!p?'placeholder':''}"><span class="fighter-bar"></span><span class="fighter-text"><strong>${p?esc(p.name):settled?T('Wolny los'):T('Zwycięzca poprzedniej walki')}</strong>${p?'<small>'+esc(p.club)+(p.champion?' <span class="champion-star" title="'+T('Mistrz Polski / Europy')+'">★</span>':'')+'</small>':''}</span>${m.winner===id&&id?icon('check','win-check'):''}</div>`;
 const active=interactive&&managesTournament(workspace.user,state.tournament)&&state.tournament.status!=='finished'&&!m.auto&&(m.ready||m.recorded);
 const tag=active?'button':'div';
 return `<${tag} class="match ${m.auto?'bye':''} ${m.recorded?'complete':''} ${m.ready?'ready':''} ${compact?'compact':''}" ${active?`data-action="match" data-match="${m.id}" aria-label="${T('Walka {n}: {a} i {b}. {status}',{n:m.number,a:esc(a?.name),b:esc(b?.name),status:title})}"`:''}><div class="match-label"><span>${m.auto?T('AWANS'):T('WALKA {n}',{n:String(m.number).padStart(2,'0')})}</span><span>${m.recorded?icon('check'):m.ready?'<i class="tiny-dot"></i>':''}${title}</span></div>${row(a,m.a,m.aSettled,'blue')}${row(b,m.b,m.bSettled,'red')}</${tag}>`;
}
function bracketHtml(draw,interactive=true,opts={}){
 const rounds=opts.roundSet||resolveDraw(draw),n=rounds.length,fullTotal=opts.totalRounds||n,startRound=opts.startRound||0;
 const round=Math.min(ui.round,n-1);
 return `<div class="mobile-round-control"><label for="round-select">${T('Runda')}</label><select id="round-select" data-control="round">${rounds.map((r,i)=>`<option value="${i}" ${i===round?'selected':''}>${roundName(i+startRound,fullTotal)}</option>`).join('')}</select></div><div class="bracket-scroll ${opts.screen?'screen-bracket':''}"><div class="bracket-tree" style="--rounds:${n};--slots:${rounds[0].length}">${rounds.map((matches,i)=>`<section class="round ${i===round?'mobile-active':''}" aria-label="${roundName(i+startRound,fullTotal)}"><div class="round-title"><span>${roundName(i+startRound,fullTotal)}</span><small>${i===n-1?icon('trophy'):String(i+1).padStart(2,'0')}</small></div><div class="round-matches">${matches.map(m=>`<div class="match-position ${m.auto&&!m.winner?'empty-position':''}">${matchHtml(m,{interactive})}</div>`).join('')}</div></section>`).join('')}</div></div>`;
}
function categoryCard(c){const d=state.draws[c.id],done=d&&resolveDraw(d).at(-1)[0].winner;return `<button class="category-card ${selected()?.id===c.id?'selected':''}" data-action="category" data-id="${esc(c.id)}"><span class="cat-card-top"><span>${c.code}</span>${c.underfilled?badge(T('{n} os.',{n:c.athletes.length}),'warning'):done?badge(T('Zakończona'),'success'):'<span class="category-number">'+T('{n} os.',{n:c.athletes.length})+'</span>'}</span><strong>${esc(ruleLabel(c.title))}</strong><span class="cat-sub">${esc(ruleLabel(c.ageLabel))} · ${ruleLabel(c.sexLabel)}</span><span class="cat-band">${esc(ruleLabel(c.band))}${c.gradeType==='cup'&&c.event!=='forms'?' · '+gradeName('cup'):''}${c.gradeType==='dan'&&c.event!=='forms'?' · '+gradeName('dan'):''}</span></button>`;}
function listView(c,print=false){return `<div class="list-description">${icon('clipboard')}<div><strong>${T('Lista startowa')}</strong><p>${T('Wzór roboczy. Punktacja i kolejność prób wymagają regulaminu od trenera.')}</p></div></div><div class="table-wrap"><table class="roster-table start-list"><thead><tr><th>${T('Nr')}</th><th>${T('Zawodnik')}</th><th>${T('Klub')}</th><th>${T('Próba 1')}</th><th>${T('Próba 2')}</th><th>${T('Wynik')}</th></tr></thead><tbody>${c.athletes.map((a,i)=>`<tr><td>${i+1+(c.printOffset||0)}</td><td><strong>${esc(a.name)}</strong></td><td>${esc(a.club)}</td><td>—</td><td>—</td><td>—</td></tr>`).join('')}</tbody></table></div>`;}
function drawsPage(){
 const {items,unassigned}=allCats();let c=selected();if(!c)return shell('<div class="empty-state">'+T('Brak zgłoszeń. Dodaj pierwszego zawodnika.')+'</div>',T('Kategorie i drabinki'),T('Zgłoszenia automatycznie tworzą kategorie.'),button(icon('plus')+' '+T('Dodaj zawodnika'),'add','primary'));
 ui.category=c.id;
 const query=ui.search.toLocaleLowerCase('pl');
 const filtered=items.filter(x=>(ui.event==='all'||x.event===ui.event)&&(ui.filter!=='attention'||x.underfilled)&&[ruleText(x.title),ruleText(x.subtitle),x.code].join(' ').toLocaleLowerCase('pl').includes(query));
 if(filtered.length&&!filtered.some(x=>x.id===c.id)){c=filtered[0];ui.category=c.id;ui.round=0;}
 const d=ensureDraw(c),rounds=d?resolveDraw(d):null,final=rounds?.at(-1)[0],conflicts=d?clubConflicts(d,c.athletes):0;
 const warning=unassigned.length+items.filter(x=>x.underfilled).length;
 let content=`${stats()}${warning?`<div class="notice"><span class="notice-icon">${icon('alert')}</span><p><strong>${T('Sprawdź zgłoszenia przed losowaniem.')}</strong> ${T('{n} kategorie mają mniej niż 3 osoby',{n:items.filter(x=>x.underfilled).length})}${unassigned.length?' · '+T('{n} start wymaga przypisania',{n:unassigned.length}):''}.</p><button data-action="attention">${T('Zobacz szczegóły')} ${icon('arrow')}</button></div>`:''}<div class="workspace-toolbar"><div class="segmented" role="group" aria-label="${T('Filtr kategorii')}"><button class="${ui.filter==='all'?'active':''}" data-filter="all">${T('Wszystkie')} <span>${items.length}</span></button><button class="${ui.filter==='attention'?'active':''}" data-filter="attention">${T('Wymagają uwagi')} <span>${items.filter(x=>x.underfilled).length}</span></button></div><label class="event-filter"><span class="sr-only">${T('Konkurencja')}</span><select data-control="event"><option value="all">${T('Wszystkie konkurencje')}</option>${Object.keys(EVENTS).map(k=>`<option value="${k}" ${ui.event===k?'selected':''}>${eventName(k)}</option>`).join('')}</select></label></div><div class="draw-workspace"><aside class="category-panel" aria-label="${T('Kategorie')}"><div class="category-search">${icon('search')}<input type="search" id="category-search" placeholder="${T('Szukaj kategorii…')}" aria-label="${T('Szukaj kategorii')}" value="${esc(ui.search)}"></div><div class="category-list">${filtered.map(categoryCard).join('')||'<div class="empty-state small-empty">'+T('Brak pasujących kategorii.')+'</div>'}</div></aside><section class="draw-panel"><div class="mobile-category"><label for="category-select">${T('Wybierz kategorię')}</label><select id="category-select" data-control="category">${filtered.map(x=>`<option value="${esc(x.id)}" ${x.id===c.id?'selected':''}>${x.code} · ${esc(ruleText(x.title))} · ${esc(ruleText(x.subtitle))} (${x.athletes.length})</option>`).join('')}</select></div><div class="draw-header"><div><div class="draw-eyebrow"><span class="category-code">${c.code}</span>${badge(c.underfilled?T('Wymaga decyzji'):final?.winner?T('Zakończona'):d&&Object.keys(d.results).length?T('W toku'):c.type==='list'?T('Lista startowa'):T('Gotowa do rozegrania'),c.underfilled?'warning':final?.winner?'success':'teal')}</div><h2>${esc(ruleText(c.title))}</h2><p>${esc(ruleText(c.subtitle))}${c.event!=='forms'&&c.gradeType!=='all'?' · '+gradeName(c.gradeType):''}</p></div><div class="draw-meta"><span>${icon('users')} ${T('{n} zawodników',{n:c.athletes.length})}</span><span>${icon('shield')} ${T('{n} klubów',{n:new Set(c.athletes.map(a=>a.club)).size})}</span></div></div><div class="draw-subbar"><span>${icon(c.type==='list'?'clipboard':'bracket')} ${c.type==='list'?T('Konkurencja punktowa'):d?T('System pucharowy · {n} miejsc',{n:d.size}):T('Minimum 3 zawodników')}</span>${d&&managesTournament(workspace.user,state.tournament)&&state.tournament.status!=='finished'?`<button data-action="redraw" class="text-btn" ${Object.keys(d.results).length?'disabled title="'+T('Zapisano wyniki — losowanie zablokowane')+'"':''}>${icon('refresh')} ${T('Losuj ponownie')}</button>`:''}</div>${c.underfilled?`<div class="empty-state underfilled"><div class="empty-illustration">${icon('users')}</div><h3>${c.athletes.length===1?T('Jeden zawodnik to jeszcze nie turniej.'):T('Ta kategoria potrzebuje trzeciej osoby.')}</h3><p>${T('Wymagane są co najmniej 3 osoby. Organizator powinien zdecydować o kategorii przed losowaniem.')}</p><div class="waiting-athletes">${c.athletes.map(a=>`<div><span class="avatar">${initials(a.name)}</span><span><strong>${esc(a.name)}</strong><small>${esc(a.club)}</small></span></div>`).join('')}</div>${button(T('Przejdź do zgłoszeń'),'roster','secondary')}</div>`:c.type==='list'?listView(c):d?bracketHtml(d):`<div class="empty-state"><div class="empty-illustration">${icon('bracket')}</div><h3>${c.athletes.length>64?T('Kategoria wymaga podziału'):T('Zgłoszenia są gotowe do losowania.')}</h3><p>${c.athletes.length>64?T('Maksymalnie 64 osoby w drabince.'):T('Zapisz rozstawienie, aby rozpocząć walki.')}</p>${c.athletes.length<=64&&managesTournament(workspace.user,state.tournament)&&state.tournament.status!=='finished'?button(T('Losuj drabinkę'),'create-draw','primary'):''}</div>`}${d?`<div class="draw-footnote"><span class="${conflicts?'warning-text':''}">${icon(conflicts?'alert':'shield')}${conflicts?T('{n} pary z tego samego klubu — sprawdź losowanie',{n:conflicts}):T('Rozdzielono kluby w pierwszych pewnych parach')}</span><span>${icon('info')} ${T('Kliknij walkę, aby wpisać zwycięzcę')}</span></div>${final?.winner?`<div class="winner-banner">${icon('trophy')}<div><small>${T('ZWYCIĘZCA KATEGORII')}</small><strong>${esc(athlete(final.winner)?.name)}</strong></div>${badge(T('Finał zakończony'),'success')}<p>${T('Brąz: zasada do ustalenia.')}</p></div>`:''}`:''}</section></div>`;
 if(!filtered.length)content=content.replace(/<section class="draw-panel">[\s\S]*<\/section><\/div>$/, '<section class="draw-panel empty-state"><h3>'+T('Brak pasujących kategorii')+'</h3><p>'+T('Zmień filtr konkurencji lub wyszukiwaną frazę.')+'</p></section></div>');
 return shell(content,T('Kategorie i drabinki'),T('Od pierwszego losowania do ostatniej walki.'),button(icon('print')+' '+T('Drukuj'),'print')+button(icon('screen')+' '+T('Ekran hali'),'project','primary'));
}
function overviewPage(){const {items,unassigned}=allCats();const completed=Object.values(state.draws).filter(d=>resolveDraw(d).at(-1)[0].winner).length;return shell(`${stats()}<div class="overview-grid"><section class="panel overview-main"><div class="panel-heading"><div><div class="eyebrow">${T('NA DOBRY POCZĄTEK')}</div><h2>${T('Wszystko na swoim miejscu.')}</h2><p>${T('Trzy kroki od zgłoszeń do gotowego turnieju.')}</p></div>${icon('bracket')}</div><div class="workflow-step"><span>01</span><div><h3>${T('Zbierz zgłoszenia')}</h3><p>${T('Klub dodaje zawodników oraz ich konkurencje. Kategorie uzupełniają się automatycznie.')}</p></div><button data-page="athletes" class="icon-btn" aria-label="${T('Zobacz zawodników')}">${icon('arrow')}</button></div><div class="workflow-step"><span>02</span><div><h3>${T('Sprawdź wagę i obecność')}</h3><p>${T('Jedna korekta aktualizuje wszystkie starty zawodnika.')}</p></div><button data-page="checkin" class="icon-btn" aria-label="${T('Przejdź do kontroli')}">${icon('arrow')}</button></div><div class="workflow-step"><span>03</span><div><h3>${T('Rozegraj turniej')}</h3><p>${T('Zapisuj zwycięzców. Drabinki są gotowe do druku i wyświetlenia.')}</p></div><button data-page="draws" class="icon-btn" aria-label="${T('Przejdź do drabinek')}">${icon('arrow')}</button></div></section><section class="panel attention-card"><div class="panel-heading"><h2>${T('Do sprawdzenia')}</h2>${icon('alert')}</div>${items.filter(c=>c.underfilled).map(c=>`<button class="attention-row" data-action="category" data-id="${esc(c.id)}"><span class="attention-count">${c.athletes.length}</span><div><strong>${esc(ruleText(c.title))}</strong><small>${esc(ruleText(c.subtitle))}</small></div>${icon('right')}</button>`).join('')}${unassigned.map(x=>`<div class="attention-row"><span class="attention-count">!</span><div><strong>${esc(x.athlete.name)}</strong><small>${esc(translateMessage(x.reason))}</small></div></div>`).join('')}<p class="muted small">${T('Kategorie z mniej niż 3 osobami pozostają bez losowania.')}</p></section></div><section class="panel activity"><div class="panel-heading"><h2>${T('Ostatnie zmiany')}</h2><span>${T('{n} kategorii zakończonych',{n:completed})}</span></div>${state.activity.length?state.activity.slice(0,6).map(x=>`<div class="activity-row">${icon('check')}<span>${esc(translateMessage(x.text))}</span><time>${new Date(x.time).toLocaleTimeString(locale(),{hour:'2-digit',minute:'2-digit',timeZone:'Europe/Warsaw'})}</time></div>`).join(''):'<div class="empty-activity">'+icon('clock')+' '+T('Tutaj pojawią się zapisane wyniki, zgłoszenia i korekty.')+'</div>'}</section>`,T('Przegląd turnieju'),esc(state.tournament.name)+' · '+formatDate(state.tournament.date)+' · '+esc(state.tournament.city),button(icon('plus')+' '+T('Dodaj zawodnika'),'add','primary'));}
function rosterPage(checkin=false){const user=workspace.user,t=state.tournament,q=ui.rosterSearch.toLocaleLowerCase('pl');const list=state.athletes.filter(a=>(a.name+' '+a.club).toLocaleLowerCase('pl').includes(q)&&(ui.rosterFilter==='all'||a.presence===ui.rosterFilter));return shell(`<div class="notice info-notice">${icon(checkin?'scale':'users')}<p>${checkin?'<strong>'+T('Kontrola wyłącznie tego turnieju.')+'</strong> '+T('Waga i nieobecność aktualizują starty tutaj.'):'<strong>'+esc(t.name)+'</strong> '+T('Zgłoszenia są kopiami danych z kartoteki.')+' '+statusName(t.status)+'.'}</p></div><section class="panel roster-panel"><div class="roster-toolbar"><div class="search-field">${icon('search')}<input id="roster-search" type="search" placeholder="${T('Szukaj zawodnika lub klubu…')}" aria-label="${T('Szukaj zawodnika lub klubu')}" value="${esc(ui.rosterSearch)}"></div><select data-control="roster-filter" aria-label="${T('Status kontroli')}">${[['all',T('Wszystkie statusy')],['pending',T('Oczekują na kontrolę')],['present',T('Obecni')],['absent',T('Nieobecni')]].map(([v,l])=>`<option value="${v}" ${ui.rosterFilter===v?'selected':''}>${l}</option>`).join('')}</select><span class="muted small">${T('{n} osób',{n:list.length})}</span></div><div class="table-wrap"><table class="roster-table"><thead><tr><th>${T('Zawodnik')}</th><th>${T('Klub')}</th><th>${checkin?T('Zgłoszona → kontrolna'):T('Wiek / stopień')}</th><th>${checkin?T('Status'):T('Konkurencje')}</th><th>${T('Działania')}</th></tr></thead><tbody>${list.map(a=>`<tr class="${a.presence==='absent'?'absent':''}"><td data-label="${T('Zawodnik')}"><div class="athlete-cell"><span class="avatar">${initials(a.name)}</span><span><strong>${esc(a.name)}</strong><small>${a.height} cm${a.champion?' · '+T('Mistrz PL / EU'):''}</small></span></div></td><td data-label="${T('Klub')}">${esc(a.club)}</td><td data-label="${checkin?T('Waga'):T('Wiek / stopień')}">${checkin?`${formatNumber(a.weight)} → <strong>${a.actualWeight!=null?formatNumber(a.actualWeight):'—'}</strong> kg`:`${T('{n} lat',{n:a.age})} · ${gradeLabel(a.grade,a.gradeType)}`}</td><td data-label="${checkin?T('Status'):T('Konkurencje')}">${checkin?badge(a.presence==='present'?T('Po kontroli'):a.presence==='absent'?T('Nieobecny'):T('Do kontroli'),a.presence==='present'?'success':a.presence==='absent'?'neutral':'warning'):`<span class="event-tags">${a.events.map(e=>`<span>${eventName(e)}</span>`).join('')}</span>`}</td><td class="row-action"><div class="row-buttons">${checkin?(managesTournament(user,t)&&t.status!=='finished'?button(T('Sprawdź'),'check-athlete','small-btn',`data-id="${a.id}"`):'<span class="muted small">'+T('Podgląd')+'</span>'):canEditEntry(a)?button(T('Edytuj'),'edit-entry','small-btn',`data-id="${a.profileId}"`)+button(T('Wycofaj'),'remove-entry','small-btn danger-text',`data-id="${a.id}"`):'<span class="muted small">'+T('Podgląd')+'</span>'}</div></td></tr>`).join('')||'<tr><td colspan="5" class="empty-state"><h3>'+T('Brak zgłoszeń w tym turnieju.')+'</h3><p>'+T('Dodaj zawodników z bazy albo utwórz nowe kartoteki.')+'</p></td></tr>'}</tbody></table></div></section>`,checkin?T('Kontrola startowa'):user.role==='club'?T('Zgłoszenia klubu'):T('Zgłoszenia do turnieju'),esc(t.name)+' · '+formatDate(t.date),!checkin&&canEnter(user,t)?button(icon('plus')+' '+T('Nowy zawodnik'),'new-entry')+button(icon('users')+' '+T('Dodaj z bazy'),'entry-picker','primary'):'');}
function rulesPage(){return shell(`<div class="notice info-notice">${icon('info')}<p>${T('Reguły na podstawie dokumentu trenera Bogusława. Poniższe niejasności pozostają otwarte — prototyp nie nadaje im statusu zatwierdzonego regulaminu.')}</p></div><div class="rules-grid">${RULE_ISSUES.map((r,i)=>`<section class="panel rule-card"><div class="rule-number">${String(i+1).padStart(2,'0')}</div>${badge(T('Do potwierdzenia'),'warning')}<h2>${T(r.title)}</h2><p>${T(r.detail)}</p></section>`).join('')}</div><section class="panel rule-summary"><h2>${T('Ustalone w specyfikacji')}</h2><ul><li>${T('Minimum 3 zawodników w kategorii.')}</li><li>${T('Unikanie pierwszych walk pomiędzy zawodnikami tego samego klubu, gdy jest to możliwe.')}</li><li>${T('Pierwszeństwo wolnego losu dla mistrzów Polski i Europy, gdy jest dostępny.')}</li><li>${T('Układy i walki: drabinka. Techniki specjalne i testy siły: lista startowa.')}</li><li>${T('Zmiana obecności dotyczy wszystkich startów zawodnika.')}</li><li>${T('Na wydruku: pełna nazwa konkurencji, grupa wieku, płeć oraz stopień lub limit.')}</li></ul></section>`,T('Zasady turnieju'),T('Czytelne reguły. Widoczne miejsca wymagające decyzji.'));}
function architecturePage(){return shell(`<section class="panel architecture-intro"><div class="eyebrow">${T('MATBRAVO · WIELE TURNIEJÓW')}</div><h2>${T('Jeden zawodnik. Kolejne turnieje.')}</h2><p>${T('Kartoteka należy do klubu. Zgłoszenie do turnieju jest osobnym rekordem z wiekiem, stopniem, konkurencjami i wagą na dane zawody. Kontrola i wyniki nie zmieniają innych turniejów.')}</p><div class="tech-flow"><span>${T('Baza zawodników')}</span>${icon('arrow')}<span>${T('Zgłoszenia do turniejów')}</span>${icon('arrow')}<span>${T('Kontrola · drabinki · wyniki')}</span></div><a class="btn primary" href="./architecture.html" target="_blank" rel="noopener">${T('Architektura i wdrożenie')} ${icon('external')}</a></section><div class="rules-grid"><section class="panel rule-card"><h2>${T('Konta i role')}</h2><p>${T('Logowanie e-mailem i hasłem. Administrator przydziela role i klub, Edytor prowadzi własne turnieje, Reprezentant zgłasza zawodników swojego klubu.')}</p></section><section class="panel rule-card"><h2>${isDemo?T('Status podglądu Sites'):T('Połączenie z serwerem')}</h2><p>${isDemo?T('W tym podglądzie konta i dane pozostają w tej przeglądarce. Do wspólnej pracy klubów potrzebne jest uruchomienie przygotowanego backendu PHP i bazy MySQL na Waszym hostingu.'):T('Aplikacja korzysta z backendu PHP i bazy MySQL. Uprawnienia są sprawdzane na serwerze przy każdej operacji.')}</p></section></div>`,T('O projekcie'),'MatBravo · MEDUCASE · matbravo.com');}
function render(){
 if(!workspace){renderPublic();return;}
 syncState();if(location.hash.startsWith('#screen')&&workspace.user.role!=='club'){renderScreen();return;}
 if(location.hash.startsWith('#guest')){ui.page='tournaments';history.replaceState(null,'','#tournaments');}
 document.body.classList.remove('projection');
 if(ui.page==='accounts'&&workspace.user.role!=='admin')ui.page='tournaments';
 if(['overview','checkin','draws','screen'].includes(ui.page)&&workspace.user.role==='club')ui.page='athletes';
 if(['overview','athletes','checkin','draws'].includes(ui.page)&&!state.tournament.id)ui.page='tournaments';
 const pages={tournaments:tournamentsPage,database:databasePage,accounts:accountsPage,draws:drawsPage,overview:overviewPage,athletes:()=>rosterPage(false),checkin:()=>rosterPage(true),rules:rulesPage,architecture:architecturePage};
 document.querySelector('#app').innerHTML=(pages[ui.page]||tournamentsPage)();document.title='MatBravo — '+({tournaments:T('Turnieje'),database:T('Baza zawodników'),accounts:T('Konta i role'),draws:T('Drabinki'),athletes:T('Zgłoszenia'),checkin:T('Kontrola startowa'),overview:T('Przegląd'),rules:T('Zasady turnieju'),architecture:T('O projekcie')}[ui.page]||T('Turnieje'));
}
function navigate(page){ui.page=page;ui.menu=false;history.replaceState(null,'','#'+page);render();window.scrollTo({top:0});}
function modal(title,body,actions='',large=false){
 previousFocus=document.activeElement;afterModalClose=null;
 document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${large?'wide':''}" role="dialog" aria-modal="true" data-revision="${workspace?.revision||0}" aria-labelledby="modal-title" tabindex="-1"><header><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="${T('Zamknij okno')}">${icon('close')}</button></header><div class="modal-body">${body}</div>${actions?'<footer class="modal-actions">'+actions+'</footer>':''}</section></div>`;
 document.body.classList.add('modal-open');const form=document.querySelector('.modal form');if(form&&workspace)form.dataset.revision=workspace.revision;document.querySelector('.modal input,.modal select,.modal button')?.focus();
}
function closeModal(){const after=afterModalClose;afterModalClose=null;document.querySelector('#modal-root').innerHTML='';document.body.classList.remove('modal-open');if(after)after();else if(previousFocus?.isConnected)previousFocus.focus();}
function showAttention(){const {items,unassigned}=allCats();modal(T('Zgłoszenia wymagające uwagi'),`<p class="modal-lead">${T('Te starty wymagają decyzji przed losowaniem.')}</p>${items.filter(c=>c.underfilled).map(c=>`<button class="attention-row" data-action="category" data-id="${esc(c.id)}"><span class="attention-count">${c.athletes.length}</span><div><strong>${esc(ruleText(c.title))}</strong><small>${esc(ruleText(c.subtitle))}</small></div>${icon('right')}</button>`).join('')}${unassigned.map(x=>`<div class="attention-row"><span class="attention-count">!</span><div><strong>${esc(x.athlete.name)} · ${eventName(x.event)}</strong><small>${esc(translateMessage(x.reason))}</small></div></div>`).join('')}`,button(T('Zasady turnieju'),'rules')+button(T('Rozumiem'),'close-modal','primary'));}
function matchModal(id){
 const c=selected(),d=ensureDraw(c),m=resolveDraw(d).flat().find(m=>m.id===id);if(!m)return;
 modal(T('Walka {n}',{n:String(m.number).padStart(2,'0')}),`<p class="modal-lead">${esc(ruleText(c.title))} · ${esc(ruleText(c.subtitle))}</p><p class="field-label">${T('Wskaż zwycięzcę')}</p><div class="winner-options">${[m.a,m.b].map((id,i)=>{const a=athlete(id);return `<button class="winner-option ${i?'red':'blue'} ${m.winner===id?'selected':''}" data-action="choose-winner" data-match="${m.id}" data-id="${id}"><span class="avatar">${initials(a.name)}</span><span><strong>${esc(a.name)}</strong><small>${esc(a.club)}</small></span>${m.winner===id?icon('check'):icon('right')}</button>`;}).join('')}</div><p class="muted small">${T('Zwycięzca automatycznie przechodzi do kolejnej rundy.')} ${isDemo?T('Zapis dotyczy danych demonstracyjnych.'):T('Wynik jest zapisany dla tego turnieju.')}</p><div class="form-error" role="alert"></div>`,(m.recorded?button(T('Wycofaj wynik'),'clear-winner','danger-text',`data-match="${id}"`):'')+button(T('Anuluj'),'close-modal'));
}
function checkModal(id){const a=athlete(id);modal(T('Kontrola startowa'),`<div class="check-athlete"><span class="avatar large">${initials(a.name)}</span><div><h3>${esc(a.name)}</h3><p>${esc(a.club)} · ${gradeLabel(a.grade,a.gradeType)}</p></div></div><form id="check-form" data-id="${id}"><div class="form-grid"><label>${T('Status obecności')}<select name="presence"><option value="present" ${a.presence!=='absent'?'selected':''}>${T('Obecny')}</option><option value="absent" ${a.presence==='absent'?'selected':''}>${T('Nieobecny')}</option></select></label><label>${T('Waga kontrolna (kg)')}<input name="actualWeight" type="number" min="10" max="250" step="0.1" value="${a.actualWeight??a.weight}"></label></div><div class="weight-summary"><span>${T('Waga zgłoszona')} <strong>${formatNumber(a.weight)} kg</strong></span><span>${T('Tolerancja')} <strong>200 g*</strong></span></div><div id="check-impact" class="impact-box"></div><p class="muted small">* ${T('Robocza interpretacja: tolerancja przy górnej granicy zgłoszonej kategorii. Do zatwierdzenia przez trenera.')}</p><div class="form-error" role="alert"></div></form>`,button(T('Anuluj'),'close-modal')+'<button class="btn primary" form="check-form" type="submit">'+T('Zapisz kontrolę')+'</button>');updateImpact();}
function checkCandidate(form){const a=athlete(form.dataset.id),f=new FormData(form);const value=String(f.get('actualWeight')).trim();const w=value===''?NaN:Number(value);return {...a,presence:f.get('presence'),actualWeight:f.get('presence')==='absent'?a.actualWeight:w};}
function updateImpact(){const form=document.querySelector('#check-form');if(!form)return;const before=athlete(form.dataset.id),after=checkCandidate(form);const box=document.querySelector('#check-impact');if(after.presence==='absent'){box.innerHTML=`${icon('alert')}<div><strong>${T('Usunięcie ze wszystkich startów')}</strong><p>${after.events.map(eventName).join(' · ')}. ${T('Zgłoszenie pozostanie w historii.')}</p></div>`;return;}if(!Number.isFinite(after.actualWeight)){box.innerHTML='<span>'+T('Podaj wagę kontrolną.')+'</span>';return;}const changed=after.events.filter(e=>classify(before,e).id!==classify(after,e).id);box.innerHTML=icon(changed.length?'refresh':'check')+`<div><strong>${changed.length?T('Kategoria zmieni się automatycznie'):T('Kategorie pozostają bez zmian')}</strong><p>${changed.length?changed.map(e=>eventName(e)+': '+(ruleLabel(classify(before,e).band)||T('do decyzji'))+' → '+(ruleLabel(classify(after,e).band)||T('do decyzji'))).join('<br>'):T('Potwierdzisz obecność i wagę zawodnika.')}</p></div>`;}
function printModal(){const c=selected();modal(T('Drukuj drabinki i listy'),`<form id="print-form"><fieldset><legend>${T('Zakres wydruku')}</legend><label class="radio-card"><input type="radio" name="scope" value="selected" checked><span><strong>${T('Bieżąca kategoria')}</strong><small>${esc(ruleText(c?.title||''))} · ${esc(ruleText(c?.subtitle||''))}</small></span></label><label class="radio-card"><input type="radio" name="scope" value="all"><span><strong>${T('Wszystkie obsadzone kategorie')}</strong><small>${T('{n} kategorii · jedna kategoria na stronie lub kilka arkuszy',{n:allCats().items.length})}</small></span></label></fieldset><label class="field-label print-format">${T('Format papieru')}<select name="format"><option value="A4">${T('A4 — poziomo')}</option><option value="A3">${T('A3 — poziomo')}</option></select></label><p class="muted small">${T('Możesz wybrać „Zapisz jako PDF” w oknie drukowania. Kategorie z mniej niż 3 osobami otrzymają listę z oznaczeniem „Do decyzji”.')}</p></form>`,button(T('Anuluj'),'close-modal')+'<button type="submit" form="print-form" class="btn primary">'+icon('print')+' '+T('Otwórz podgląd')+'</button>');}
function printBracket(draw,rounds=null,startRound=0){const rr=rounds||resolveDraw(draw);return `<div class="print-tree" style="--print-rounds:${rr.length}">${rr.map((matches,i)=>`<section class="print-round"><h3>${roundName(i+startRound,Math.log2(draw.size))}</h3><div>${matches.map(m=>`<div class="print-match-position">${matchHtml(m,{interactive:false,compact:true})}</div>`).join('')}</div></section>`).join('')}</div>`;}
function doPrint(scope,format){
 ui.print={scope,format};const cats=scope==='all'?allCats().items:[selected()].filter(Boolean);const sheets=[];
 for(const c of cats){
  const d=ensureDraw(c);
  const base=(body,suffix='')=>`<article class="print-sheet"><header><div><strong class="print-brand">MatBravo.</strong><span>${esc(state.tournament.name)} · ${esc(state.tournament.city)}</span></div><span>${c.code}${suffix?' · '+suffix:''}</span></header><h1>${esc(ruleText(c.title))}</h1><p class="print-subtitle">${esc(ruleText(c.subtitle))}${c.event!=='forms'&&c.gradeType!=='all'?' · '+gradeName(c.gradeType):''} · ${T('{n} zawodników',{n:c.athletes.length})}${d?' · '+T('wersja {n}',{n:d.revision}):''}</p>${c.underfilled?'<p class="print-warning">'+T('DO DECYZJI — mniej niż 3 zawodników. Brak losowania.')+'</p>':''}${body}<footer><span>${isDemo?T('DEMO · DANE PRZYKŁADOWE'):'MATBRAVO'} · ${new Date().toLocaleDateString(locale(),{timeZone:'Europe/Warsaw'})}</span><a href="https://mdcse.com">${T('Wykonano przez')} <img src="./assets/meducase.png" alt="MEDUCASE"></a></footer></article>`;
  if(c.type==='list'||!d){const pages=Math.ceil(c.athletes.length/12);for(let p=0;p<pages;p++){const part={...c,athletes:c.athletes.slice(p*12,(p+1)*12),printOffset:p*12};sheets.push(base(listView(part,true),pages>1?T('Lista {n} / {total}',{n:p+1,total:pages}):''));}continue;}
  const rounds=resolveDraw(d);
  if(d.size<=16){sheets.push(base(printBracket(d)));continue;}
  const segments=d.size/16;
  for(let s=0;s<segments;s++){
   const part=rounds.slice(0,4).map((r,i)=>r.slice(s*(8/2**i),(s+1)*(8/2**i)));
   sheets.push(base(printBracket(d,part),T('Sekcja {n} / {total}',{n:s+1,total:segments})));
  }
  sheets.push(base(printBracket(d,rounds.slice(4),4),T('Finały sekcji')));
 }
 document.querySelector('#print-root').innerHTML=sheets.join('');
 document.querySelector('#print-root').dataset.format=format;
 document.querySelector('#print-root').style.setProperty('--sheet-height',format==='A3'?'272mm':'185mm');
 document.querySelector('#print-root').style.setProperty('--preview-width',format==='A3'?'420mm':'297mm');
 let style=document.querySelector('#print-page-size');if(!style){style=document.createElement('style');style.id='print-page-size';document.head.append(style);}style.textContent=`@page {size:${format==='A3'?'A3':'A4'} landscape;margin:10mm;}`;
 closeModal();
 document.body.classList.add('print-preview');
 let toolbar=document.querySelector('#print-toolbar');if(!toolbar){toolbar=document.createElement('div');toolbar.id='print-toolbar';document.body.append(toolbar);}
 toolbar.innerHTML=button(icon('left')+' '+T('Wróć do turnieju'),'exit-print')+`<span>${T('Podgląd wydruku · {format} poziomo · {sheets}',{format,sheets:sheets.length+' '+plural(sheets.length,T('arkusz'),T('arkusze'),T('arkuszy'))})}</span>`+button(icon('print')+' '+T('Drukuj / zapisz PDF'),'native-print','primary');
 window.scrollTo({top:0});
}
function renderScreen(){
 document.body.classList.add('projection');
 const params=new URLSearchParams(location.hash.split('?')[1]||''),items=allCats().items;
 const c=items.find(x=>x.id===params.get('category'))||selected();
 if(!c){document.querySelector('#app').innerHTML='<main class="screen-empty">'+T('Brak kategorii do wyświetlenia.')+' <a href="#draws">'+T('Wróć')+'</a></main>';return;}
 ui.category=c.id;const d=ensureDraw(c);
 let parts=1,roundSet=null,startRound=0,partLabel=T('Cała drabinka');
 if(d&&d.size>8){
  const all=resolveDraw(d);parts=d.size/8;
  ui.screenPart=Math.min(ui.screenPart,parts);
  if(ui.screenPart===parts){roundSet=all.slice(3);startRound=3;partLabel=T('Finały sekcji');}
  else{roundSet=all.slice(0,3).map((r,i)=>r.slice(ui.screenPart*(4/2**i),(ui.screenPart+1)*(4/2**i)));partLabel=T('Sekcja {n} / {total}',{n:String.fromCharCode(65+ui.screenPart),total:String.fromCharCode(64+parts)});}
 }
 document.querySelector('#app').innerHTML=`<main class="arena"><header class="arena-header"><a class="brand" href="#draws">${logo}</a><div class="arena-event"><strong>${esc(state.tournament.name)}</strong><span>TAEKWONDO · ${esc(state.tournament.city).toUpperCase()}</span></div><div class="arena-clock"><span class="pulse-dot"></span>${esc(state.tournament.mat)} <strong id="arena-time">${new Date().toLocaleTimeString(locale(),{hour:'2-digit',minute:'2-digit',timeZone:'Europe/Warsaw'})}</strong></div></header><div class="arena-controls"><select data-control="screen-category" aria-label="${T('Kategoria na ekranie')}">${items.map(x=>`<option value="${esc(x.id)}" ${x.id===c.id?'selected':''}>${x.code} · ${esc(ruleText(x.title))} · ${esc(ruleText(x.subtitle))}</option>`).join('')}</select>${d&&d.size>8?`<select data-control="screen-part" aria-label="${T('Sekcja drabinki')}">${Array.from({length:parts},(_,i)=>`<option value="${i}" ${ui.screenPart===i?'selected':''}>${T('Sekcja {n}',{n:String.fromCharCode(65+i)})}</option>`).join('')}<option value="${parts}" ${ui.screenPart===parts?'selected':''}>${T('Finały sekcji')}</option></select>${button(icon('refresh')+' '+(ui.screenAuto?T('Zatrzymaj zmianę'):T('Zmieniaj co 15 s')),'screen-auto')}`:''}${button(icon('expand')+' '+T('Pełny ekran'),'fullscreen')}${button(icon('left')+' '+T('Panel'),'exit-screen')}</div><div class="arena-title"><span class="category-code">${c.code}</span><h1>${esc(ruleText(c.title))}</h1><p>${esc(ruleText(c.subtitle))}${d&&d.size>8?' <span class="arena-part">'+partLabel+'</span>':''}</p></div>${c.underfilled?'<div class="arena-message">'+T('Kategoria oczekuje na decyzję organizatora.')+'<br><small>'+T('Minimum 3 zawodników.')+'</small></div>':c.type==='list'?listView(c):d?bracketHtml(d,false,{screen:true,roundSet:roundSet||resolveDraw(d),totalRounds:Math.log2(d.size),startRound}):'<div class="arena-message">'+T('Oczekiwanie na losowanie organizatora.')+'</div>'}<div class="arena-caption"><span>${isDemo?T('DEMO · Synchronizacja kart tej przeglądarki'):T('Dane z serwera · odświeżanie co 15 s')}</span><span>${d?T('WERSJA {n}',{n:d.revision}):T('LISTA STARTOWA')}</span></div>${footer()}</main>`;
 document.title='MatBravo — '+T('Ekran hali');
}
function tournamentsPage(){
 const user=workspace.user,q=ui.tournamentSearch.toLocaleLowerCase('pl'),list=workspace.tournaments.filter(t=>(t.name+' '+t.city).toLocaleLowerCase('pl').includes(q));
 return shell(`<div class="workspace-summary"><div><strong>${workspace.tournaments.length}</strong><span>${T('Turniejów')}</span></div><div><strong>${workspace.profiles.filter(p=>!p.archived).length}</strong><span>${user.role==='club'?T('Zawodników klubu'):T('W bazie zawodników')}</span></div><div><strong>${workspace.tournaments.filter(t=>t.status==='open').length}</strong><span>${T('Otwartych zapisów')}</span></div></div><div class="collection-toolbar"><div class="search-field">${icon('search')}<input id="tournament-search" type="search" aria-label="${T('Szukaj turnieju')}" placeholder="${T('Szukaj turnieju lub miasta…')}" value="${esc(ui.tournamentSearch)}"></div><span class="muted small">${T('Jedna baza zawodników. Wiele turniejów.')}</span></div><div class="tournament-grid">${list.map(t=>`<article class="tournament-card ${activeId===t.id?'current-tournament':''}"><div class="tournament-card-top"><span class="tournament-symbol">${icon('trophy')}</span>${badge(statusName(t.status),t.status==='open'?'teal':t.status==='finished'?'neutral':'warning')}</div><h2>${esc(t.name)}</h2><p>${formatDate(t.date)} <span>·</span> ${esc(t.city)}</p><div class="tournament-card-meta"><span>${icon('users')} ${user.role==='club'?T('{n} zgłoszeń klubu',{n:t.entries.length}):T('{n} zgłoszeń',{n:t.entries.length})}</span><span>${icon('bracket')} ${user.role==='club'?T('Twoje zgłoszenia'):T('{n} drabinek',{n:Object.keys(t.draws).length})}</span></div><div class="tournament-card-actions">${button(T('Otwórz turniej')+' '+icon('arrow'),'open-tournament','primary',`data-id="${t.id}"`)}${managesTournament(user,t)?button(icon('settings'),'edit-tournament','secondary icon-only',`data-id="${t.id}" aria-label="${T('Ustawienia: {name}',{name:esc(t.name)})}"`):''}</div></article>`).join('')||'<section class="panel empty-state"><h3>'+T('Tu pojawią się turnieje.')+'</h3><p>'+ (user.role==='club'?T('Administrator lub Edytor musi najpierw otworzyć zapisy.'):T('Utwórz pierwszy turniej, a potem dodaj zgłoszenia z bazy zawodników.'))+'</p></section>'}</div>`,T('Turnieje'),user.role==='club'?T('Wybierz turniej i zgłoś zawodników swojego klubu.'):T('Twórz kolejne zawody i zarządzaj zgłoszeniami w jednym miejscu.'),['admin','editor'].includes(user.role)?button(icon('plus')+' '+T('Nowy turniej'),'new-tournament','primary'):'');
}
function tournamentForm(id){const t=workspace.tournaments.find(t=>t.id===id)||{name:'',city:'',date:'',status:'draft',mat:T('Mata 1')};modal(id?T('Ustawienia turnieju'):T('Nowy turniej'),`<form id="tournament-form" data-id="${id||''}"><div class="form-grid"><label class="span-two">${T('Nazwa turnieju')}<input name="name" required maxlength="100" value="${esc(t.name)}" placeholder="${T('np. Puchar Wiosny 2027')}"></label><label>${T('Data zawodów')}<input name="date" type="date" required value="${t.date}" ${t.entries?.length?'readonly':''}></label><label>${T('Miasto')}<input name="city" required maxlength="100" value="${esc(t.city)}"></label><label>${T('Status')}<select name="status">${Object.keys(STATUSES).map(v=>`<option value="${v}" ${t.status===v?'selected':''}>${statusName(v)}</option>`).join('')}</select></label><label>${T('Nazwa maty')}<input name="mat" maxlength="50" required value="${esc(t.mat)}"></label></div><p class="muted small form-note">${T('„Zapisy otwarte” pozwalają klubom dodawać zawodników. Zakończony turniej zachowuje historię i wyniki.')} ${t.entries?.length?T('Data jest zablokowana, ponieważ są już zgłoszenia.'):''}</p><div class="form-error" role="alert"></div></form>`,button(T('Anuluj'),'close-modal')+'<button class="btn primary" form="tournament-form" type="submit">'+(id?T('Zapisz zmiany'):T('Utwórz turniej'))+'</button>');}
function databasePage(){const q=ui.databaseSearch.toLocaleLowerCase('pl'),list=workspace.profiles.filter(a=>(ui.showArchive||!a.archived)&&(a.name+' '+clubName(a.clubId)).toLocaleLowerCase('pl').includes(q));return shell(`<div class="notice info-notice">${icon('info')}<p><strong>${T('Kartoteka zostaje na kolejne zawody.')}</strong> ${T('Zmiana danych w bazie nie nadpisuje wcześniejszych zgłoszeń i wyników.')}</p></div><section class="panel roster-panel"><div class="roster-toolbar"><div class="search-field">${icon('search')}<input id="database-search" aria-label="${T('Szukaj w bazie zawodników')}" type="search" placeholder="${T('Szukaj zawodnika lub klubu…')}" value="${esc(ui.databaseSearch)}"></div><label class="checkbox-label"><input type="checkbox" data-control="archive" ${ui.showArchive?'checked':''}> ${T('Pokaż archiwum')}</label><span class="muted small">${T('{n} osób',{n:list.length})}</span></div><div class="table-wrap"><table class="roster-table"><thead><tr><th>${T('Zawodnik')}</th><th>${T('Klub')}</th><th>${T('Data urodzenia / stopień')}</th><th>${T('Turnieje')}</th><th><span class="sr-only">${T('Działania')}</span></th></tr></thead><tbody>${list.map(a=>`<tr class="${a.archived?'absent':''}"><td data-label="${T('Zawodnik')}"><div class="athlete-cell"><span class="avatar">${initials(a.name)}</span><span><strong>${esc(a.name)}</strong><small>${a.archived?T('Archiwum'):a.sex==='M'?T('Mężczyzna / chłopiec'):T('Kobieta / dziewczynka')}</small></span></div></td><td data-label="${T('Klub')}">${esc(clubName(a.clubId))}</td><td data-label="${T('Urodzenie / stopień')}">${a.birthDate?formatDate(a.birthDate):'<span class="warning-text">'+T('Uzupełnij datę')+'</span>'}<span class="separator">·</span>${gradeLabel(a.grade,a.gradeType)}</td><td data-label="${T('Turnieje')}">${workspace.tournaments.filter(t=>t.entries.some(e=>e.profileId===a.id)).length}</td><td class="row-action"><div class="row-buttons">${!a.archived?button(T('Zgłoś'),'register-profile','small-btn',`data-id="${a.id}"`):''}${managesProfile(workspace.user,a)?button(T('Edytuj'),'edit-profile','small-btn',`data-id="${a.id}"`):''}</div></td></tr>`).join('')||'<tr><td colspan="5" class="empty-state">'+T('Brak zawodników. Dodaj pierwszą osobę do bazy.')+'</td></tr>'}</tbody></table></div></section>`,T('Baza zawodników'),workspace.user.role==='club'?T('Kartoteka Twojego klubu. Wybieraj te same osoby do kolejnych turniejów.'):T('Wspólna kartoteka, oddzielna od zgłoszeń turniejowych.'),button(icon('plus')+' '+T('Nowy zawodnik'),'new-profile','primary'));}
function profileForm(id,register=false){const a=workspace.profiles.find(a=>a.id===id)||{name:'',clubId:workspace.user.clubId,sex:'M',birthDate:'',gradeType:'cup',grade:6,weight:60,height:170,events:['forms'],champion:false};modal(id?T('Kartoteka zawodnika'):register?T('Nowy zawodnik i zgłoszenie'):T('Nowy zawodnik w bazie'),`<form id="profile-form" data-id="${id||''}" data-register="${register?'yes':''}"><div class="form-grid"><label class="span-two">${T('Imię i nazwisko')}<input name="name" value="${esc(a.name)}" required maxlength="100" autocomplete="off"></label><label class="span-two">${T('Klub')}<select name="clubId" ${workspace.user.role==='club'?'disabled':''}>${workspace.clubs.map(c=>`<option value="${c.id}" ${a.clubId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label>${T('Data urodzenia')}<input type="date" name="birthDate" ${a.legacyAge?'':'required'} value="${a.birthDate||''}" max="${new Date().toISOString().slice(0,10)}"></label><label>${T('Płeć')}<select name="sex"><option value="M" ${a.sex==='M'?'selected':''}>${T('Mężczyzna / chłopiec')}</option><option value="F" ${a.sex==='F'?'selected':''}>${T('Kobieta / dziewczynka')}</option></select></label>${measureFields(a)}<fieldset class="span-two"><legend>${register?T('Domyślne konkurencje na ten turniej'):T('Domyślne konkurencje')}</legend>${eventFields(a.events)}</fieldset><label class="checkbox-label span-two"><input type="checkbox" name="champion" ${a.champion?'checked':''}> ${T('Mistrz Polski lub Europy')}</label></div><p class="muted small form-note">${register?T('Po zapisie dodamy osobę do bazy i zgłosimy ją do: {name}.',{name:esc(state.tournament.name)}):T('Dane służą do kolejnych zgłoszeń. Dotychczasowe turnieje zachowują swoje kopie.')} ${T('Wiek wyliczamy na dzień zawodów; zasada wymaga zatwierdzenia przez trenera.')}</p><div class="form-error" role="alert"></div></form>`,(id?button(a.archived?T('Przywróć z archiwum'):T('Archiwizuj kartotekę'),'archive-profile','danger-text',`data-id="${id}" data-archived="${a.archived?'false':'true'}"`):'')+button(T('Anuluj'),'close-modal')+'<button class="btn primary" type="submit" form="profile-form">'+(register?T('Zapisz i zgłoś'):T('Zapisz zawodnika'))+'</button>',true);}
function measureFields(a){return `<label>${T('Waga zgłoszona (kg)')}<input name="weight" type="number" min="10" max="250" step="0.1" value="${a.weight}" required></label><label>${T('Wzrost (cm)')}<input name="height" type="number" min="70" max="250" step="1" value="${a.height}" required></label><label>${T('Rodzaj stopnia')}<select name="gradeType"><option value="cup" ${a.gradeType==='cup'?'selected':''}>${gradeName('cup')}</option><option value="dan" ${a.gradeType==='dan'?'selected':''}>Dan</option></select></label><label>${T('Stopień')}<input name="grade" type="number" min="1" max="10" value="${a.grade}" required></label>`;}
function eventFields(events){return `<div class="event-checkboxes">${Object.keys(EVENTS).map(k=>`<label class="checkbox-label"><input type="checkbox" name="events" value="${k}" ${events?.includes(k)?'checked':''}>${eventName(k)}</label>`).join('')}</div>`;}
function pickerModal(){const t=state.tournament;const list=workspace.profiles.filter(a=>!a.archived&&!t.entries.some(e=>e.profileId===a.id));modal(T('Dodaj zawodnika z bazy'),`<p class="modal-lead">${esc(t.name)} · ${T('{n} dostępnych osób',{n:list.length})}</p><input class="picker-search" id="picker-search" type="search" placeholder="${T('Szukaj zawodnika…')}" aria-label="${T('Szukaj zawodnika w bazie')}"><div class="profile-picker">${list.map(a=>`<button class="picker-row" data-action="register-profile" data-id="${a.id}" data-search="${esc((a.name+' '+clubName(a.clubId)).toLocaleLowerCase('pl'))}"><span class="avatar">${initials(a.name)}</span><span><strong>${esc(a.name)}</strong><small>${esc(clubName(a.clubId))}</small></span>${icon('plus')}</button>`).join('')||'<p class="empty-state">'+T('Wszystkie dostępne osoby są już zgłoszone albo baza jest pusta.')+'</p>'}</div><p class="picker-empty" hidden>${T('Brak pasujących osób.')}</p>`,button(icon('plus')+' '+T('Utwórz nowego zawodnika'),'new-entry')+button(T('Zamknij'),'close-modal'));}
function entryForm(profileId,update=false){const profile=workspace.profiles.find(p=>p.id===profileId);if(!profile)throw Error('Nie znaleziono zawodnika.');const t=state.tournament;if(!t.id||!canEnter(workspace.user,t))throw Error('Wybierz turniej z otwartymi zapisami.');const current=update?t.entries.find(a=>a.profileId===profileId):null,a=current||profile;const age=profile.birthDate?ageAt(profile.birthDate,t.date):current?.age??'';modal(update?T('Edytuj zgłoszenie'):T('Zgłoś zawodnika'),`<div class="check-athlete"><span class="avatar large">${initials(profile.name)}</span><div><h3>${esc(profile.name)}</h3><p>${esc(clubName(profile.clubId))}</p></div></div><p class="entry-event-name">${icon('trophy')} ${esc(t.name)} · ${formatDate(t.date)}</p><form id="entry-form" data-id="${profileId}" data-update="${update?'yes':''}"><div class="form-grid"><label class="span-two">${T('Wiek w dniu zawodów')}<input name="age" type="number" min="7" max="100" value="${age}" required ${profile.birthDate?'readonly':''}><small>${profile.birthDate?T('Wyliczony z daty urodzenia.'):T('Starsza kartoteka nie ma daty urodzenia. Potwierdź wiek dla tego turnieju.')}</small></label>${measureFields(a)}<fieldset class="span-two"><legend>${T('Konkurencje w tym turnieju')}</legend>${eventFields(a.events)}</fieldset><label class="checkbox-label span-two"><input type="checkbox" name="champion" ${a.champion?'checked':''}> ${T('Mistrz Polski lub Europy')}</label></div><p class="muted small form-note">${T('Waga, stopień, konkurencje i późniejsza kontrola dotyczą wyłącznie tego turnieju.')}</p><div class="form-error" role="alert"></div></form>`,button(T('Anuluj'),'close-modal')+'<button type="submit" class="btn primary" form="entry-form">'+(update?T('Zapisz zgłoszenie'):T('Zgłoś do turnieju'))+'</button>',true);}
function canEditEntry(a){const u=workspace.user,t=state.tournament,p=workspace.profiles.find(x=>x.id===a.profileId);return canEnter(u,t)&&(managesTournament(u,t)||u.role==='club'&&a.clubId===u.clubId||u.role==='editor'&&p?.createdBy===u.id);}
function accountsPage(){return shell(`<div class="notice info-notice">${icon('shield')}<p><strong>${T('Role przydziela Administrator.')}</strong> ${T('Reprezentanci widzą tylko kartotekę i zgłoszenia swojego klubu. Konto można zablokować bez usuwania historii.')}</p></div><section class="panel roster-panel"><div class="table-wrap"><table class="roster-table"><thead><tr><th>${T('E-mail')}</th><th>${T('Klub')}</th><th>${T('Rola')}</th><th>${T('Status')}</th><th>${T('Działania')}</th></tr></thead><tbody>${workspace.users.map(u=>`<tr><td data-label="${T('E-mail')}"><strong>${esc(u.email)}</strong>${u.id===workspace.user.id?' <small>'+T('(Ty)')+'</small>':''}</td><td data-label="${T('Klub')}">${esc(clubName(u.clubId))}</td><td data-label="${T('Rola')}">${esc(roleName(u.role))}</td><td data-label="${T('Status')}">${badge(u.active?T('Aktywne'):T('Zablokowane'),u.active?'success':'warning')}</td><td class="row-action">${button(T('Zarządzaj'),'edit-account','small-btn',`data-id="${u.id}"`)}</td></tr>`).join('')}</tbody></table></div></section><div class="role-grid"><article class="panel"><h3>${roleName('admin')}</h3><p>${T('Wszystkie turnieje, kartoteki, zgłoszenia, wyniki oraz konta i role.')}</p></article><article class="panel"><h3>${roleName('editor')}</h3><p>${T('Tworzy i prowadzi własne turnieje, dodaje zawodników i edytuje własne kartoteki. Nie zarządza kontami.')}</p></article><article class="panel"><h3>${roleName('club')}</h3><p>${T('Dodaje i aktualizuje zawodników swojego klubu. Zgłasza ich do istniejących turniejów z otwartymi zapisami.')}</p></article></div>`,T('Konta i role'),T('Prosty dostęp: klub, e-mail, hasło i zakres uprawnień.'),button(icon('plus')+' '+T('Nowe konto'),'new-account','primary'));}
function accountForm(id){const u=workspace.users.find(u=>u.id===id)||{email:'',clubId:'',role:'club',active:true};modal(id?T('Zarządzaj kontem'):T('Nowe konto'),`<form id="account-form" data-id="${id||''}"><div class="form-grid"><label class="span-two">${T('E-mail')}<input name="email" type="email" required maxlength="254" value="${esc(u.email)}" autocomplete="off"></label><label class="span-two">${T('Klub')}<select name="clubId"><option value="">${T('Nowy klub — wpisz nazwę poniżej')}</option>${workspace.clubs.map(c=>`<option value="${c.id}" ${u.clubId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label class="span-two">${T('Nazwa nowego klubu')}<input name="clubName" maxlength="100" placeholder="${T('Wypełnij tylko dla nowego klubu')}"></label><label>${T('Rola')}<select name="role">${Object.keys(ROLES).map(r=>`<option value="${r}" ${u.role===r?'selected':''}>${roleName(r)}</option>`).join('')}</select></label><label>${T('Status')}<select name="active"><option value="yes" ${u.active?'selected':''}>${T('Aktywne')}</option><option value="no" ${!u.active?'selected':''}>${T('Zablokowane')}</option></select></label><label class="span-two">${id?T('Nowe hasło (opcjonalnie)'):T('Hasło')}<input name="password" type="password" autocomplete="new-password" minlength="12" maxlength="72" ${id?'':'required'}><small>${T('Minimum 12 znaków.')} ${id?T('Zmiana hasła kończy poprzednie sesje konta.'):''}</small></label></div><div class="form-error" role="alert"></div>${isDemo?'<p class="muted small form-note">'+T('To konto testowe, dostępne wyłącznie w tej przeglądarce. Użyj hasła przeznaczonego do demonstracji.')+'</p>':''}</form>`,button(T('Anuluj'),'close-modal')+'<button class="btn primary" type="submit" form="account-form">'+(id?T('Zapisz zmiany'):T('Utwórz konto'))+'</button>');}
function myAccount(){const u=workspace.user;modal(T('Moje konto'),`<div class="account-summary"><strong>${esc(u.email)}</strong><p>${esc(clubName(u.clubId))} · ${roleName(u.role)}</p></div><form id="password-form"><label class="field-label">${T('Obecne hasło')}<input name="currentPassword" type="password" required autocomplete="current-password"></label><label class="field-label form-note">${T('Nowe hasło')}<input name="password" type="password" required minlength="12" maxlength="72" autocomplete="new-password"></label><p class="muted small form-note">${T('Minimum 12 znaków.')} ${T('Pozostałe sesje zostaną wylogowane.')}</p><div class="form-error" role="alert"></div></form>`,button(T('Zamknij'),'close-modal')+'<button class="btn primary" type="submit" form="password-form">'+T('Zmień hasło')+'</button>');}
function renderLogin(message=''){
 loginMessage=message;afterModalClose=null;
 document.body.classList.remove('projection','print-preview','modal-open');document.querySelector('#modal-root').innerHTML='';
 document.querySelector('#app').innerHTML=`<main class="login-page"><div class="login-lang">${langSwitch()}</div><section class="login-story"><a class="brand" href="#tournaments">${logo}</a><div><span class="login-eyebrow">${T('TWÓJ TURNIEJ. TWÓJ ZESPÓŁ.')}</span><h1>${T('Od zgłoszenia<br>do finału.')}</h1><p>${T('Wspólna baza zawodników, kolejne turnieje i czytelne drabinki. Wszystko w jednym miejscu.')}</p><div class="login-feature">${icon('users')} ${T('Konta klubów i proste zgłoszenia')}</div><div class="login-feature">${icon('trophy')} ${T('Wiele turniejów, osobna historia')}</div><div class="login-feature">${icon('screen')} ${T('Wydruk i ekran hali')}</div></div><span class="login-signature">MATBRAVO · BY MEDUCASE</span></section><section class="login-form-panel"><div class="login-form-content"><span class="eyebrow">${T('WITAJ W MATBRAVO')}</span><h2>${T('Zaloguj się')}</h2><p>${T('Użyj konta otrzymanego od Administratora.')}</p>${isDemo?'<div class="login-demo-note">'+T('Podgląd demonstracyjny · konta i dane tylko w tej przeglądarce.')+'</div>':''}<form id="login-form"><label class="field-label">${T('E-mail')}<input name="email" type="email" autocomplete="username" required placeholder="${T('twoj@klub.pl')}"></label><label class="field-label">${T('Hasło')}<input name="password" type="password" autocomplete="current-password" required></label><div class="form-error" role="alert">${esc(translateMessage(message))}</div><button class="btn primary login-submit" type="submit">${T('Zaloguj się')} ${icon('arrow')}</button></form>${isDemo?`<div class="demo-accounts"><span>${T('Sprawdź przykładową rolę')}</span>${Object.keys(ROLES).map(r=>`<button class="demo-account" data-action="demo-login" data-role="${r}">${icon(r==='admin'?'shield':r==='editor'?'clipboard':'users')}<span>${roleName(r)}</span>${icon('right')}</button>`).join('')}<p>${T('Hasło kont demo:')} <code>MatDrawDemo2026!</code></p></div>`:'<p class="login-help">'+T('Nie masz konta lub nie pamiętasz hasła? Skontaktuj się z Administratorem turnieju.')+'</p>'}</div></section>${upcomingSection()}<div class="login-foot">${footer()}</div></main>`;document.title='MatBravo — '+T('Logowanie');
 loadUpcoming();
}
// ---- Public side: "Upcoming tournaments" on the login screen, sponsor dialog, read-only guest preview ----
// Data comes only from Client.upcoming()/Client.publicTournament() (GET, no session); see backend/src/GuestView.php.
const dateAt=date=>new Date(date+'T12:00:00');
const shortDate=date=>dateAt(date).toLocaleDateString(locale(),{weekday:'short',day:'numeric',month:'short',year:'numeric'});
const longDate=date=>dateAt(date).toLocaleDateString(locale(),{weekday:'long',day:'numeric',month:'long',year:'numeric'});
function relativeDay(date){try{const days=Math.round((Date.parse(date+'T00:00:00Z')-Date.parse(warsawToday()+'T00:00:00Z'))/864e5);return days<=31?new Intl.RelativeTimeFormat(locale(),{numeric:'auto'}).format(days,'day'):new Intl.RelativeTimeFormat(locale(),{numeric:'always'}).format(Math.round(days/30.44),'month');}catch{return '';}}
function upcomingItem(t,i){
 const d=dateAt(t.date),when=relativeDay(t.date);
 return `<li><button type="button" class="upcoming-item${i===0?' is-next':''}" data-action="open-upcoming" data-id="${esc(t.id)}" aria-describedby="upcoming-hint"><span class="upcoming-date" aria-hidden="true"><small>${esc(d.toLocaleDateString(locale(),{month:'short'}).replace('.',''))}</small><strong>${d.getDate()}</strong></span><span class="upcoming-text">${i===0?`<span class="upcoming-next">${T('Najbliższy')}${when?' · '+esc(when):''}</span>`:''}<strong class="upcoming-name">${esc(t.name)}</strong><span class="upcoming-meta"><span>${icon('pin')}${esc(t.city)}</span><time datetime="${esc(t.date)}">${esc(shortDate(t.date))}</time></span></span>${icon('right','upcoming-arrow')}</button></li>`;
}
function upcomingBody(){
 const items=upcoming.data?.tournaments;
 if(items?.length)return `<ol class="upcoming-list">${items.map(upcomingItem).join('')}</ol><p class="upcoming-hint" id="upcoming-hint">${icon('eye')}<span>${T('Wybierz turniej, aby zobaczyć podgląd tylko do odczytu.')}</span></p>`;
 if(items)return `<div class="upcoming-empty">${icon('calendar')}<strong>${T('Brak zaplanowanych turniejów')}</strong><p>${T('Nowe zawody pojawią się tutaj, gdy organizator je opublikuje.')}</p></div>`;
 if(upcoming.error)return `<div class="upcoming-empty quiet"><p>${T('Terminarz jest chwilowo niedostępny.')}</p><button type="button" class="upcoming-retry" data-action="upcoming-retry">${icon('refresh')}<span>${T('Spróbuj ponownie')}</span></button></div>`;
 return `<div class="upcoming-skeleton" aria-hidden="true"><span></span><span></span><span></span></div><p class="sr-only">${T('Wczytywanie turniejów…')}</p>`;
}
const upcomingSection=()=>`<section class="login-upcoming" aria-labelledby="upcoming-title"><div class="upcoming-card"><div class="upcoming-head"><span class="upcoming-icon">${icon('calendar')}</span><div><h2 id="upcoming-title">${T('Najbliższe turnieje')}</h2><p>${T('Terminarz otwarty dla wszystkich')}</p></div></div><div class="upcoming-body" data-upcoming aria-busy="${upcoming.loading&&!upcoming.data}">${upcomingBody()}</div></div></section>`;
function paintUpcoming(){
 const el=document.querySelector('[data-upcoming]');if(!el)return;
 const hadFocus=el.contains(document.activeElement);el.innerHTML=upcomingBody();el.setAttribute('aria-busy',String(upcoming.loading&&!upcoming.data));
 if(hadFocus)el.querySelector('button')?.focus();
}
/** Loads the public list once and refreshes it after 5 minutes. Failures stay quiet: the login form never depends on it. */
function loadUpcoming(force=false){
 if(upcoming.loading||(!force&&upcoming.data&&Date.now()-upcoming.at<300000))return;
 upcoming.loading=true;upcoming.error=false;if(force)paintUpcoming();
 Client.upcoming().then(r=>{upcoming.data={tournaments:Array.isArray(r?.tournaments)?r.tournaments:[]};},()=>{upcoming.error=true;}).finally(()=>{upcoming.loading=false;upcoming.at=Date.now();paintUpcoming();});
}
function guestRouteId(){if(!location.hash.startsWith('#guest'))return null;const id=new URLSearchParams(location.hash.split('?')[1]||'').get('t');return id&&/^[A-Za-z0-9_-]{1,40}$/.test(id)?id:null;}
/** Without a session: the login page, or – for #guest?t=… – the sponsor dialog first and the guest preview only after it is closed. */
function renderPublic(){
 const id=guestRouteId();
 if(!id){guest=null;promo=null;renderLogin();return;}
 if(guest?.id===id&&guest.unlocked){renderGuest();return;}
 renderLogin();showPromo(id);
}
function fetchGuest(id){
 const known=upcoming.data?.tournaments?.find(t=>t.id===id)||(guest?.id===id?guest.known:null);
 const current=guest={id,known,status:'loading',data:null,unlocked:false,category:null};
 Client.publicTournament(id).then(data=>{current.data=data;current.status='ready';},error=>{current.status='error';current.notFound=error?.status===404;}).finally(()=>{
  if(guest!==current||workspace)return;
  if(promo?.id===id){const next=document.querySelector('.promo-next span');if(next)next.innerHTML=promoNext();}
  if(current.unlocked&&guestRouteId()===id){const refocus=!document.activeElement||document.activeElement===document.body||document.activeElement.id==='guest-title';renderGuest();if(refocus)document.querySelector('#guest-title')?.focus();}
 });
}
const promoTournament=()=>guest?.data?.tournament||guest?.known||null;
const promoNext=()=>{const t=promoTournament();return t?T('Dalej: podgląd turnieju {name}',{name:'<strong>'+esc(t.name)+'</strong>'}):T('Dalej: podgląd turnieju');};
// Inline illustration (the CSP allows no external images): a dobok with a black belt on concentric mat rings.
const promoArt=`<svg class="promo-art" viewBox="0 0 300 300" focusable="false" aria-hidden="true"><circle cx="150" cy="150" r="134" fill="none" stroke="#fff" stroke-opacity=".07" stroke-width="2"/><circle cx="150" cy="150" r="104" fill="none" stroke="#00aeef" stroke-opacity=".45" stroke-width="2" stroke-dasharray="3 9"/><circle cx="150" cy="150" r="72" fill="#00aeef" fill-opacity=".12"/><path d="M114 70 84 83c-7 3-11 8-12 15l-10 52 26 7v77h124v-77l26-7-10-52c-1-7-5-12-12-15l-30-13-36 56-36-56Z" fill="#fff"/><path d="m114 70 36 56 36-56" fill="none" stroke="#c7d9ec" stroke-width="6" stroke-linejoin="round"/><path d="M150 126v108" stroke="#dbe6f2" stroke-width="2"/><path d="M62 150l26 7M238 150l-26 7" stroke="#dbe6f2" stroke-width="2"/><rect x="88" y="176" width="124" height="15" rx="3" fill="#0b1a33"/><path d="m145 189-15 34 11 3 14-35Zm10 0 15 33-10 4-13-35Z" fill="#0b1a33"/><rect x="140" y="172" width="20" height="23" rx="5" fill="#0b1a33" stroke="#1d3a66" stroke-width="2"/><path d="M220 60l4 10 10 4-10 4-4 10-4-10-10-4 10-4Z" fill="#65c8ec"/><path d="M70 214l3 7 7 3-7 3-3 7-3-7-7-3 7-3Z" fill="#65c8ec" fill-opacity=".7"/></svg>`;
function promoHtml(){
 return `<div class="modal-backdrop promo-backdrop"><section class="modal promo" role="dialog" aria-modal="true" aria-labelledby="promo-kind promo-title" aria-describedby="promo-text promo-note" tabindex="-1"><button type="button" class="promo-close" data-action="close-modal" aria-label="${T('Zamknij reklamę i przejdź do podglądu')}" title="${T('Zamknij reklamę i przejdź do podglądu')}">${icon('close')}</button><span class="promo-kind" id="promo-kind">${esc(T(AD.label))}</span><div class="promo-visual" aria-hidden="true">${promoArt}<span class="promo-brand">${esc(AD.brand)}</span><span class="promo-tagline">${esc(T(AD.tagline))}</span></div><div class="promo-main"><div class="promo-body"><span class="promo-eyebrow">${esc(AD.brand)} · ${esc(T(AD.eyebrow))}</span><h2 id="promo-title">${esc(T(AD.headline))}</h2><p id="promo-text">${esc(T(AD.text))}</p><ul class="promo-products">${AD.products.map(p=>`<li><span class="promo-product-icon">${icon(p.icon)}</span><span><strong>${esc(T(p.title))}</strong><small>${esc(T(p.text))}</small></span></li>`).join('')}</ul><div class="promo-offer">${icon('sparkle')}<span>${esc(T(AD.offer))}</span><em>${esc(T(AD.cta))}</em></div><p class="promo-disclaimer" id="promo-note">${esc(T(AD.disclaimer))}</p></div><footer class="promo-foot"><p class="promo-next">${icon('eye')}<span>${promoNext()}</span></p><div class="promo-actions"><button type="button" class="btn secondary" data-action="promo-login">${icon('lock')} ${T('Zaloguj się')}</button><button type="button" class="btn primary" data-action="close-modal">${T('Zamknij i zobacz turniej')} ${icon('arrow')}</button></div></footer></div></section></div>`;
}
/** Sponsor dialog. Closing it (button, × or Esc) is the only way into the guest preview of that tournament. */
function showPromo(id){
 if(guest?.id!==id||guest.status==='error')fetchGuest(id);
 promo={id};previousFocus=document.activeElement;
 document.querySelector('#modal-root').innerHTML=promoHtml();afterModalClose=()=>enterGuest(id);
 document.body.classList.add('modal-open');document.querySelector('.modal.promo')?.focus();
}
function openUpcoming(id){history.pushState(null,'','#guest?t='+encodeURIComponent(id));showPromo(id);}
function enterGuest(id){promo=null;if(guest?.id!==id)fetchGuest(id);guest.unlocked=true;ui.round=0;renderGuest();document.querySelector('#guest-title')?.focus();}
function leaveGuest(){guest=null;promo=null;afterModalClose=null;if(location.hash)history.replaceState(null,'',location.pathname+location.search);renderLogin();document.querySelector('#login-form input[name="email"]')?.focus();}
const guestStates=()=>({finished:[T('Zakończona'),'success'],progress:[T('W toku'),'teal'],drawn:[T('Gotowa do rozegrania'),'teal'],pending:[T('Przed losowaniem'),'neutral'],underfilled:[T('Wymaga decyzji'),'warning'],list:[T('Lista startowa'),'neutral']});
const guestBadge=c=>{const states=guestStates(),[label,type]=states[c.state]||states.pending;return badge(label,type);};
const guestGrade=c=>c.event!=='forms'&&c.gradeType!=='all'?' · '+gradeName(c.gradeType):'';
function guestCard(c,selected){
 const [age,sex,...band]=String(c.subtitle).split(' · ');
 return `<button type="button" class="category-card ${selected?'selected':''}" data-action="guest-category" data-code="${esc(c.code)}" aria-pressed="${selected}"><span class="cat-card-top"><span>${esc(c.code)}${c.bracket?icon('bracket','guest-card-bracket'):''}</span>${c.state==='underfilled'?badge(T('{n} os.',{n:Number(c.athletes)||0}),'warning'):c.state==='finished'?badge(T('Zakończona'),'success'):'<span class="category-number">'+T('{n} os.',{n:Number(c.athletes)||0})+'</span>'}</span><strong>${esc(ruleLabel(c.title))}</strong><span class="cat-sub">${esc(ruleLabel(age))} · ${esc(ruleLabel(sex))}</span><span class="cat-band">${esc(ruleLabel(band.join(' · ')))}${guestGrade(c)}</span></button>`;
}
function guestDetail(c){
 const head=`<div class="draw-header"><div><div class="draw-eyebrow"><span class="category-code">${esc(c.code)}</span>${guestBadge(c)}</div><h2>${esc(ruleText(c.title))}</h2><p>${esc(ruleText(c.subtitle))}${guestGrade(c)}</p></div><div class="draw-meta"><span>${icon('users')} ${T('{n} zawodników',{n:Number(c.athletes)||0})}</span></div></div>`;
 if(!c.bracket){
  const [i,title,text]=c.state==='list'?['clipboard',T('Lista startowa'),T('Kolejność startów i wyniki konkurencji punktowej widzą zalogowani użytkownicy.')]:c.state==='underfilled'?['users',T('Kategoria czeka na decyzję organizatora.'),T('Do losowania potrzebne są co najmniej 3 osoby.')]:['bracket',T('Losowanie jeszcze się nie odbyło.'),T('Drabinka pojawi się tutaj, gdy organizator zapisze losowanie.')];
  return head+`<div class="empty-state guest-state"><div class="empty-illustration">${icon(i)}</div><h3>${title}</h3><p>${text}</p></div>`;
 }
 // Public brackets carry initials and club only; slot positions become local ids for the shared bracket renderer.
 const ref=i=>'s'+i,draw={size:Number(c.bracket.size),slots:c.bracket.slots.map((p,i)=>p?ref(i):null),results:Object.fromEntries(Object.entries(c.bracket.results||{}).map(([m,i])=>[m,ref(i)]))};
 state={tournament:guest.data.tournament,athletes:c.bracket.slots.flatMap((p,i)=>p?[{id:ref(i),name:p.initials,club:p.club}]:[]),draws:{},activity:[]};
 const winner=athlete(resolveDraw(draw).at(-1)[0].winner);
 return head+`<div class="draw-subbar"><span>${icon('bracket')} ${T('System pucharowy · {n} miejsc',{n:draw.size})}</span><span>${icon('eye')} ${T('Tylko do odczytu')}</span></div>${bracketHtml(draw,false)}<div class="draw-footnote"><span>${icon('lock')}${T('Zawodnicy oznaczeni inicjałami. Pełne imiona i nazwiska widzą zalogowani użytkownicy.')}</span></div>${winner?`<div class="winner-banner">${icon('trophy')}<div><small>${T('ZWYCIĘZCA KATEGORII')}</small><strong>${esc(winner.name)} <span class="guest-winner-club">${esc(winner.club)}</span></strong></div>${badge(T('Finał zakończony'),'success')}</div>`:''}`;
}
function guestCategories(d){
 const cats=d.categories||[];
 if(!cats.length)return `<section class="panel empty-state guest-empty"><div class="empty-illustration">${icon('grid')}</div><h3>${T('Kategorie pojawią się po pierwszych zgłoszeniach.')}</h3><p>${T('Organizator zbiera jeszcze zgłoszenia do tego turnieju.')}</p></section>`;
 const c=cats.find(x=>x.code===guest.category)||cats.find(x=>x.bracket)||cats[0];guest.category=c.code;
 return `<div class="guest-section-head"><h2>${T('Kategorie i drabinki')}</h2><span>${T('{n} kategorii',{n:cats.length})}</span></div><div class="draw-workspace guest-workspace"><aside class="category-panel" aria-label="${T('Kategorie')}"><div class="category-list">${cats.map(x=>guestCard(x,x.code===c.code)).join('')}</div></aside><section class="draw-panel"><div class="mobile-category"><label for="guest-category-select">${T('Wybierz kategorię')}</label><select id="guest-category-select" data-control="guest-category">${cats.map(x=>`<option value="${esc(x.code)}" ${x.code===c.code?'selected':''}>${esc(x.code)} · ${esc(ruleText(x.title))} · ${esc(ruleText(x.subtitle))} (${Number(x.athletes)||0})</option>`).join('')}</select></div>${guestDetail(c)}</section></div>`;
}
const accessCard=()=>`<aside class="access-card" aria-labelledby="access-title"><span class="access-icon">${icon('lock')}</span><div class="access-copy"><span class="access-eyebrow">${esc(T(ACCESS.eyebrow))}</span><h2 id="access-title">${esc(T(ACCESS.title))}</h2><p>${esc(T(ACCESS.text))}</p></div><ul class="access-benefits">${ACCESS.benefits.map(b=>`<li>${icon('check')}<span>${esc(T(b))}</span></li>`).join('')}</ul><div class="access-action"><button type="button" class="btn access-cta" data-action="access-cta">${esc(T(ACCESS.cta))} ${icon('arrow')}</button><small>${esc(T(ACCESS.note))}</small></div></aside>`;
function guestPage(){
 const g=guest,d=g?.data,t=d?.tournament||g?.known;
 const heading=t?`<div class="page-heading guest-heading"><div><div class="eyebrow">${T('PODGLĄD GOŚCIA · TYLKO DO ODCZYTU')}</div><h1 id="guest-title" tabindex="-1">${esc(t.name)}</h1><p class="guest-when"><span>${icon('calendar')}${esc(longDate(t.date))}</span><span>${icon('pin')}${esc(t.city)}</span></p></div><div class="heading-actions">${badge(statusName(t.status),t.status==='open'?'teal':t.status==='finished'?'neutral':'warning')}</div></div>`:`<h1 id="guest-title" class="sr-only" tabindex="-1">${T('Podgląd gościa')}</h1>`;
 let content;
 if(d){const s=d.summary;content=`<div class="stats guest-stats">${[['users',s.entries,T('Zgłoszenia')],['shield',s.clubs,T('Kluby')],['grid',s.categories,T('Kategorie')],['bracket',s.brackets,T('Drabinki')]].map(([i,n,label])=>`<div class="stat"><span class="stat-icon">${icon(i)}</span><div><strong>${Number(n)||0}</strong><span>${label}</span></div></div>`).join('')}</div>${accessCard()}${guestCategories(d)}`;}
 else if(g?.status==='error')content=`<section class="panel empty-state guest-empty"><div class="empty-illustration">${icon('alert')}</div><h3>${g.notFound?T('Ten turniej nie jest już dostępny w podglądzie.'):T('Nie udało się wczytać podglądu.')}</h3><p>${g.notFound?T('Organizator mógł go ukryć albo termin już minął.'):T('Sprawdź połączenie i spróbuj ponownie.')}</p><div class="guest-error-actions">${g.notFound?'':button(icon('refresh')+' '+T('Spróbuj ponownie'),'guest-retry')}${button(T('Wróć do logowania'),'guest-login','primary')}</div></section>`;
 else content=`<div class="guest-loading" role="status"><span class="guest-spinner" aria-hidden="true"></span>${T('Wczytywanie podglądu…')}</div>`;
 return `<div class="guest-shell"><header class="guest-bar"><div class="guest-bar-inner"><button type="button" class="brand guest-brand" data-action="guest-login" aria-label="${T('MatBravo — wróć do logowania')}">${logo}</button><span class="guest-pill">${icon('eye')}<span>${T('Podgląd gościa')}</span></span><div class="guest-bar-actions">${langSwitch()}<button type="button" class="btn guest-login" data-action="guest-login">${icon('lock')}<span>${T('Zaloguj się')}</span></button></div></div></header><main id="main" class="guest-main">${heading}${content}</main>${footer()}</div>`;
}
/** Read-only page: no forms and no write actions; the click handler accepts only the public actions below without a session. */
function renderGuest(){
 document.body.classList.remove('projection','print-preview','modal-open');
 document.querySelector('#app').innerHTML=guestPage();
 const t=guest?.data?.tournament||guest?.known;document.title='MatBravo — '+T('Podgląd gościa')+(t?' · '+t.name:'');
}
function selectGuestCategory(code,focus){if(!guest?.data)return;guest.category=code;ui.round=0;renderGuest();document.querySelector(focus)?.focus();}
function publicAction(action,el,id){
 if(action==='open-upcoming'&&id)openUpcoming(id);
 else if(action==='close-modal')closeModal();
 else if(action==='promo-login'){afterModalClose=null;closeModal();leaveGuest();}
 else if(action==='guest-login')leaveGuest();
 else if(action==='access-cta'){if(ACCESS.kind==='login')leaveGuest();}
 else if(action==='guest-category')selectGuestCategory(el.dataset.code,`.category-card[data-code="${CSS.escape(el.dataset.code)}"]`);
 else if(action==='guest-retry'&&guest){fetchGuest(guest.id);guest.unlocked=true;renderGuest();document.querySelector('#guest-title')?.focus();}
 else if(action==='upcoming-retry')loadUpcoming(true);
}
function syncState(){
 if(!workspace)return;
 const fromScreen=location.hash.startsWith('#screen')?new URLSearchParams(location.hash.split('?')[1]||'').get('tournament'):null;
 if(fromScreen)activeId=fromScreen;
 if(!workspace.tournaments.some(t=>t.id===activeId))activeId=workspace.tournaments[0]?.id||null;
 const t=workspace.tournaments.find(t=>t.id===activeId)||{name:'',city:'',date:'',entries:[],draws:{},activity:[]};
 state={tournament:t,athletes:t.entries,draws:t.draws,activity:t.activity};
}
function switchTournament(id){activeId=id;sessionStorage.setItem('matdraw.activeTournament',id);ui.category=null;ui.search='';ui.event='all';ui.filter='all';ui.round=0;ui.screenPart=0;ui.rosterSearch='';closeModal();navigate(workspace.user.role==='club'?'athletes':'overview');}
const clubName=id=>workspace?.clubs.find(c=>c.id===id)?.name||T('Klub');
const formatDate=date=>date?new Date(date+'T12:00:00').toLocaleDateString(locale(),{day:'numeric',month:'long',year:'numeric'}):T('Brak daty');
async function commit(type,payload,expected=Number(document.querySelector('.modal')?.dataset.revision||workspace.revision)){
 if(saving)throw Error('Trwa zapisywanie. Poczekaj na potwierdzenie.');
 saving=true;
 try{const res=await Client.command(type,payload,expected);workspace=res.workspace;syncState();return res.result;}
 finally{saving=false;}
}
async function handleError(error,form){
 if(error.status===401){workspace=null;closeModal();renderLogin(error.message);return;}
 if(error.status===409){try{workspace=await Client.bootstrap();syncState();render();if(form)form.dataset.revision=workspace.revision;const dialog=document.querySelector('.modal');if(dialog)dialog.dataset.revision=workspace.revision;}catch{}}
 const message=translateMessage(error.message),box=form?.querySelector('.form-error')||document.querySelector('.form-error');if(box)box.textContent=message;else toast(message);
}
function entryPayload(f){return {age:Number(f.get('age')),weight:Number(f.get('weight')),height:Number(f.get('height')),gradeType:f.get('gradeType'),grade:Number(f.get('grade')),events:f.getAll('events'),champion:f.has('champion')};}
function project(){const c=selected();window.open(location.pathname+'#screen?tournament='+encodeURIComponent(activeId)+'&category='+encodeURIComponent(c?.id||''),'matdraw-screen-'+activeId);}
document.addEventListener('click',async event=>{
 const lang=event.target.closest('[data-set-lang]');if(lang){setLanguage(lang.dataset.setLang);return;}
 const page=event.target.closest('[data-page]');if(page){event.preventDefault();closeModal();navigate(page.dataset.page);return;}
 const f=event.target.closest('[data-filter]');if(f){ui.filter=f.dataset.filter;render();return;}
 const el=event.target.closest('[data-action]');if(!el)return;
 const action=el.dataset.action,id=el.dataset.id;
 try{
  if(action==='demo-login'){el.disabled=true;const email={admin:'admin',editor:'editor',club:'club'}[el.dataset.role]+'@matdraw.example';workspace=await Client.login(email,'MatDrawDemo2026!');navigate('tournaments');return;}
  if(!workspace){publicAction(action,el,id);return;}
  if(action==='menu'){ui.menu=!ui.menu;render();}
  else if(action==='logout'){await Client.logout();workspace=null;closeModal();renderLogin();}
  else if(action==='refresh'){workspace=await Client.bootstrap();render();toast(T('Dane odświeżone.'));}
  else if(action==='new-tournament')tournamentForm();
  else if(action==='edit-tournament')tournamentForm(id);
  else if(action==='open-tournament')switchTournament(id);
  else if(action==='new-profile')profileForm();
  else if(action==='edit-profile')profileForm(id);
  else if(action==='archive-profile'){await commit('profile.archive',{id,archived:el.dataset.archived==='true'});closeModal();render();toast(T('Kartoteka zaktualizowana. Dotychczasowe zgłoszenia zachowane.'));}
  else if(action==='new-entry'||action==='add'){if(!canEnter(workspace.user,state.tournament))throw Error('Zapisy są zamknięte.');profileForm(null,true);}
  else if(action==='entry-picker')pickerModal();
  else if(action==='register-profile')entryForm(id);
  else if(action==='edit-entry')entryForm(id,true);
  else if(action==='remove-entry')modal(T('Wycofać zgłoszenie?'),`<p>${T('Wycofasz {name} z turnieju {tournament}. Kartoteka i inne turnieje pozostaną dostępne.',{name:'<strong>'+esc(athlete(id)?.name)+'</strong>',tournament:'<strong>'+esc(state.tournament.name)+'</strong>'})}</p>`,button(T('Anuluj'),'close-modal')+button(T('Wycofaj zgłoszenie'),'confirm-remove-entry','primary',`data-id="${id}"`));
  else if(action==='confirm-remove-entry'){await commit('entry.remove',{tournamentId:activeId,id});closeModal();render();toast(T('Zgłoszenie wycofane.'));}
  else if(action==='new-account')accountForm();
  else if(action==='edit-account')accountForm(id);
  else if(action==='my-account')myAccount();
  else if(action==='category'){ui.category=id;ui.round=0;closeModal();navigate('draws');}
  else if(action==='attention')showAttention();
  else if(action==='close-modal')closeModal();
  else if(action==='rules'){closeModal();navigate('rules');}
  else if(action==='roster')navigate('athletes');
  else if(action==='project')project();
  else if(action==='print')printModal();
  else if(action==='native-print')window.print();
  else if(action==='exit-print'){document.body.classList.remove('print-preview');window.scrollTo({top:0});}
  else if(action==='check-athlete')checkModal(id);
  else if(action==='match')matchModal(el.dataset.match);
  else if(action==='choose-winner'){await commit('result.save',{tournamentId:activeId,categoryId:ui.category,matchId:el.dataset.match,winnerId:id});closeModal();render();toast(T('Wynik zapisany. Zwycięzca przechodzi do kolejnej rundy.'));}
  else if(action==='clear-winner'){await commit('result.clear',{tournamentId:activeId,categoryId:ui.category,matchId:el.dataset.match});closeModal();render();toast(T('Wynik wycofany.'));}
  else if(action==='create-draw'){await commit('draw.create',{tournamentId:activeId,categoryId:ui.category});render();toast(T('Losowanie zapisane.'));}
  else if(action==='redraw'){const c=selected();modal(T('Wylosować drabinkę ponownie?'),`<p>${T('Zmieni się rozstawienie w kategorii {category}.',{category:'<strong>'+esc(ruleText(c.title))+' · '+esc(ruleText(c.subtitle))+'</strong>'})}</p><p>${T('Wyniki innych kategorii i turniejów pozostaną zachowane.')}</p>`,button(T('Anuluj'),'close-modal')+button(T('Losuj ponownie'),'confirm-redraw','primary'));}
  else if(action==='confirm-redraw'){await commit('draw.create',{tournamentId:activeId,categoryId:ui.category});closeModal();render();toast(T('Nowe rozstawienie zapisane.'));}
  else if(action==='screen-auto'){ui.screenAuto=!ui.screenAuto;renderScreen();}
  else if(action==='fullscreen'){if(!document.fullscreenElement)document.documentElement.requestFullscreen().catch(()=>toast(T('Pełny ekran nie jest dostępny.')));else document.exitFullscreen();}
  else if(action==='exit-screen'){if(document.fullscreenElement)document.exitFullscreen();navigate('draws');}
 }catch(error){el.disabled=false;await handleError(error);}
});
document.addEventListener('change',event=>{
 const el=event.target;if(el.closest('#check-form'))updateImpact();const control=el.dataset.control;
 if(control==='tournament'){switchTournament(el.value);}
 else if(control==='archive'){ui.showArchive=el.checked;render();}
 else if(control==='event'){ui.event=el.value;render();}
 else if(control==='category'){ui.category=el.value;ui.round=0;render();}
 else if(control==='round'){ui.round=Number(el.value);render();}
 else if(control==='roster-filter'){ui.rosterFilter=el.value;render();}
 else if(control==='screen-part'){ui.screenPart=Number(el.value);renderScreen();}
 else if(control==='guest-category'&&!workspace)selectGuestCategory(el.value,'#guest-category-select');
 else if(control==='screen-category'){ui.screenPart=0;location.hash='screen?tournament='+encodeURIComponent(activeId)+'&category='+encodeURIComponent(el.value);}
});
function filterRender(id){const input=document.querySelector('#'+id),start=input?.selectionStart;render();const next=document.querySelector('#'+id);if(next){next.focus();try{next.setSelectionRange(start,start);}catch{}}}
document.addEventListener('input',event=>{
 const el=event.target,fields={'category-search':'search','roster-search':'rosterSearch','database-search':'databaseSearch','tournament-search':'tournamentSearch'};
 if(fields[el.id]){ui[fields[el.id]]=el.value;filterRender(el.id);}
 if(el.id==='picker-search'){let visible=0;document.querySelectorAll('.picker-row').forEach(row=>{row.hidden=!row.dataset.search.includes(el.value.toLocaleLowerCase('pl'));if(!row.hidden)visible++;});document.querySelector('.picker-empty').hidden=visible>0;}
 if(el.closest('#check-form'))updateImpact();
});
document.addEventListener('submit',async event=>{
 const ids=['login-form','tournament-form','profile-form','entry-form','account-form','password-form','check-form','print-form'];
 if(!ids.includes(event.target.id))return;event.preventDefault();
 const form=event.target,f=new FormData(form),submit=event.submitter,revision=Number(form.dataset.revision||workspace?.revision);
 if(submit?.disabled)return;if(submit)submit.disabled=true;
 const errorBox=form.querySelector('.form-error');if(errorBox)errorBox.textContent='';
 try{
  if(form.id==='login-form'){workspace=await Client.login(f.get('email'),f.get('password'));navigate('tournaments');return;}
  if(form.id==='print-form'){doPrint(f.get('scope'),f.get('format'));return;}
  if(form.id==='tournament-form'){const result=await commit('tournament.save',{id:form.dataset.id||undefined,name:f.get('name'),city:f.get('city'),date:f.get('date'),status:f.get('status'),mat:f.get('mat')},revision);activeId=result.id;sessionStorage.setItem('matdraw.activeTournament',activeId);}
  else if(form.id==='profile-form'){
   const p={id:form.dataset.id||undefined,name:f.get('name'),clubId:f.get('clubId')||workspace.user.clubId,birthDate:f.get('birthDate'),sex:f.get('sex'),...entryPayload(f)};
   if(form.dataset.register==='yes')p.registration={tournamentId:activeId,...entryPayload(f)};
   await commit('profile.save',p,revision);
  }else if(form.id==='entry-form')await commit('entry.save',{tournamentId:activeId,profileId:form.dataset.id,update:form.dataset.update==='yes',...entryPayload(f)},revision);
  else if(form.id==='account-form')await commit('account.save',{id:form.dataset.id||undefined,email:f.get('email'),clubId:f.get('clubId'),clubName:f.get('clubName'),role:f.get('role'),active:f.get('active')==='yes',password:f.get('password')||undefined},revision);
  else if(form.id==='password-form')await commit('account.password',{id:workspace.user.id,currentPassword:f.get('currentPassword'),password:f.get('password')},revision);
  else if(form.id==='check-form')await commit('checkin.save',{tournamentId:activeId,id:form.dataset.id,presence:f.get('presence'),actualWeight:f.get('actualWeight')},revision);
  closeModal();render();toast(T('Zapisano zmiany.'));
 }catch(error){await handleError(error,form);}finally{if(submit?.isConnected)submit.disabled=false;}
});
document.addEventListener('keydown',event=>{
 const modalEl=document.querySelector('.modal');if(!modalEl)return;
 if(event.key==='Escape'){event.preventDefault();closeModal();}
 if(event.key==='Tab'){const focusable=[...modalEl.querySelectorAll('button:not([disabled]),input:not([disabled]),select:not([disabled]),a[href]')],first=focusable[0],last=focusable.at(-1),inside=focusable.includes(document.activeElement);if(event.shiftKey&&(document.activeElement===first||!inside)){event.preventDefault();last?.focus();}else if(!event.shiftKey&&(document.activeElement===last||!inside)){event.preventDefault();first?.focus();}}
});
window.addEventListener('storage',async e=>{if(e.key===LANGUAGE_KEY&&LANGUAGES.includes(e.newValue)){setLanguage(e.newValue,{persist:false});return;}if(!workspace||e.key!==Client.dataKey)return;try{workspace=await Client.bootstrap();if(!document.querySelector('.modal'))render();}catch(error){await handleError(error);}});
window.addEventListener('hashchange',()=>{if(!location.hash.startsWith('#screen'))ui.page=location.hash.slice(1)||'tournaments';render();});
setInterval(()=>{const el=document.querySelector('#arena-time');if(el)el.textContent=new Date().toLocaleTimeString(locale(),{hour:'2-digit',minute:'2-digit',timeZone:'Europe/Warsaw'});},30000);
setInterval(async()=>{if(workspace&&location.hash.startsWith('#screen')){try{workspace=await Client.bootstrap();syncState();if(ui.screenAuto){const d=ensureDraw(selected());if(d&&d.size>8)ui.screenPart=(ui.screenPart+1)%(d.size/8+1);}renderScreen();}catch(error){await handleError(error);}}},15000);
ui.page=location.hash.startsWith('#screen')?'draws':location.hash.slice(1)||'tournaments';
// Language: static page texts now, and a re-render (keeping page state and typed login data) whenever it changes.
function applyStaticTexts(){const skip=document.querySelector('.skip-link');if(skip)skip.textContent=T('Przejdź do treści');document.querySelector('meta[name="description"]')?.setAttribute('content',T('Zgłoszenia, kontrola startowa i czytelne drabinki taekwondo. MatBravo — cały turniej w jednym miejscu.'));}
function rerenderLanguage(){
 applyStaticTexts();
 const focused=!!document.activeElement?.closest?.('.lang-switch');
 if(!ready){const loading=document.querySelector('.app-loading');if(loading)loading.textContent=T('Uruchamianie MatBravo…');return;}
 if(!workspace&&guestRouteId()&&guest?.unlocked)renderGuest();
 else if(!workspace){const form=document.querySelector('#login-form'),typed=form&&{email:form.elements.email.value,password:form.elements.password.value},reopen=promo?.id;renderLogin(loginMessage);const next=document.querySelector('#login-form');if(next&&typed){next.elements.email.value=typed.email;next.elements.password.value=typed.password;}if(reopen)showPromo(reopen);}
 else if(location.hash.startsWith('#screen')&&workspace.user.role!=='club')renderScreen();
 else{render();if(document.body.classList.contains('print-preview')&&ui.print)doPrint(ui.print.scope,ui.print.format);}
 if(focused)document.querySelector(`.lang-switch [data-set-lang="${getLanguage()}"]`)?.focus();
}
onLanguageChange(rerenderLanguage);
applyStaticTexts();document.title=T('MatBravo — drabinki turniejowe taekwondo');
document.querySelector('#app').innerHTML='<div class="app-loading">'+T('Uruchamianie MatBravo…')+'</div>';
try{workspace=await Client.init();ready=true;render();}catch(error){ready=true;renderLogin(error.message);}
